export const PORTAL_HTML = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KT CI5 클라우드 인프라 마스터 포털 | 114개 실무 명령어 치트시트 & 용어 설명 사전</title>\n  <script src=\"https://www.gstatic.com/antigravity/web/dev/tailwindcss.min.js\"></script>\n  <style>\n    @import url('https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Pretendard:wght@400;500;600;700;800&display=swap');\n    body { font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, sans-serif; }\n    code, pre, .font-mono { font-family: 'Fira Code', monospace; }\n    .badge-basic { background-color: #10b981; color: white; }\n    .badge-std { background-color: #3b82f6; color: white; }\n    .badge-mid { background-color: #8b5cf6; color: white; }\n    .badge-adv { background-color: #f59e0b; color: white; }\n    .badge-deep { background-color: #ef4444; color: white; }\n    .active-lvl { outline: 2px solid #38bdf8; outline-offset: 1px; font-weight: 700; }\n    .active-view { background-color: #2563eb !important; color: white !important; font-weight: 700; }\n    .active-tag { background-color: #3b82f6 !important; color: white !important; border-color: #60a5fa !important; }\n  </style>\n</head>\n<body class=\"bg-slate-900 text-slate-100 min-h-screen\">\n\n  <!-- Header -->\n  <header class=\"border-b border-slate-800 bg-slate-950/90 sticky top-0 z-50 backdrop-blur-md\">\n    <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3.5 flex flex-col md:flex-row md:items-center md:justify-between gap-4\">\n      <div class=\"flex items-center space-x-3\">\n        <div class=\"w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 via-indigo-600 to-cyan-500 flex items-center justify-center font-bold text-xl shadow-lg shadow-blue-500/20\">\n          🐧\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <h1 class=\"text-lg font-extrabold tracking-tight text-white\">\n              KT CI5 클라우드 인프라 실무 치트시트\n            </h1>\n            <span class=\"text-[11px] px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30 font-semibold\">\n              총 114개 명령어\n            </span>\n          </div>\n          <p class=\"text-xs text-slate-400\">용어 설명(어원·개념) · 디스크 스토리지(parted/LVM/RAID) · 도커 컨테이너 · 시스템 장애 진단</p>\n        </div>\n      </div>\n\n      <!-- Quick Action Links -->\n      <div class=\"flex items-center gap-2 w-full md:w-auto flex-wrap justify-end\">\n        <nav class=\"flex items-center gap-1.5 flex-wrap\">\n          <a href=\"/study\" class=\"px-2.5 py-1.5 rounded-lg bg-indigo-950 text-indigo-300 border border-indigo-700/60 hover:bg-indigo-900 text-xs font-semibold transition-all\">📖 스터디 Hub</a>\n          <a href=\"/study/course\" class=\"px-2.5 py-1.5 rounded-lg bg-blue-950 text-blue-300 border border-blue-700/60 hover:bg-blue-900 text-xs font-semibold transition-all\">📘 강의 정리</a>\n          <a href=\"/study/calendar\" class=\"px-2.5 py-1.5 rounded-lg bg-slate-800 text-slate-200 border border-slate-700 hover:bg-slate-700 text-xs font-semibold transition-all\">🗓️ 캘린더</a>\n          <a href=\"/study/linux\" class=\"px-2.5 py-1.5 rounded-lg bg-slate-800 text-slate-200 border border-slate-700 hover:bg-slate-700 text-xs font-semibold transition-all\">🐧 리눅스 가이드</a>\n          <a href=\"/study/infra\" class=\"px-2.5 py-1.5 rounded-lg bg-slate-800 text-slate-200 border border-slate-700 hover:bg-slate-700 text-xs font-semibold transition-all\">🛠️ 인프라 가이드</a>\n          <a href=\"/updates\" class=\"px-2.5 py-1.5 rounded-lg bg-slate-800 text-slate-200 border border-slate-700 hover:bg-slate-700 text-xs font-semibold transition-all\">📢 공지</a>\n          <a href=\"/discord/verify\" class=\"px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-md shadow-indigo-500/20 transition-all\">🎫 5기 인증</a>\n        </nav>\n      </div>\n    </div>\n  </header>\n\n  <!-- Main Container -->\n  <main class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8\">\n\n    <!-- Hero / Concept Banner -->\n    <div class=\"mb-8 p-6 rounded-2xl bg-gradient-to-r from-slate-950 via-slate-900 to-indigo-950 border border-slate-800 shadow-xl\">\n      <div class=\"flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6\">\n        <div>\n          <span class=\"text-xs font-semibold uppercase tracking-wider text-indigo-400\">KT Cloud 5기 인프라 운영 & 클라우드 네이티브 실무 사전</span>\n          <h2 class=\"text-2xl font-extrabold text-white mt-1\">\"명령어를 단순 암기하지 말고, 용어의 어원과 파이프라인으로 이해하라\"</h2>\n          <p class=\"text-sm text-slate-300 mt-2 max-w-3xl leading-relaxed\">\n            명령어마다 영문 약어의 본래 어원과 한국인 엔지니어가 한눈에 이해할 수 있는 <strong class=\"text-amber-300\">💡 용어 설명</strong>을 제공합니다. \n            <strong class=\"text-cyan-400\">도커 컨테이너(30종)</strong>, <strong class=\"text-emerald-400\">스토리지·LVM·디스크(27종)</strong>, <strong class=\"text-indigo-400\">시스템·프로세스(15종)</strong>, 보안/네트워크까지 강의 실습 114개 명령어를 빠짐없이 수록했습니다.\n          </p>\n          <div class=\"mt-4 flex flex-wrap items-center gap-2 pt-3 border-t border-slate-800/80 text-xs\">\n            <span class=\"font-semibold text-slate-400 mr-1\">강의 정리 바로가기:</span>\n            <a href=\"/study/course/docker\" class=\"px-2.5 py-1 rounded-md bg-cyan-950 text-cyan-300 border border-cyan-700 hover:bg-cyan-900 transition-all font-medium\">🐳 도커 컨테이너 ➔</a>\n            <a href=\"/study/course/admin/disk\" class=\"px-2.5 py-1 rounded-md bg-emerald-950 text-emerald-300 border border-emerald-700 hover:bg-emerald-900 transition-all font-medium\">💾 디스크 관리 & LVM (0908 실습) ➔</a>\n            <a href=\"/study/course/network/flow\" class=\"px-2.5 py-1 rounded-md bg-purple-950 text-purple-300 border border-purple-700 hover:bg-purple-900 transition-all font-medium\">🌐 네트워크 기초 (IP·DNS·경로) ➔</a>\n            <a href=\"/study/linux\" class=\"px-2.5 py-1 rounded-md bg-indigo-950 text-indigo-300 border border-indigo-700 hover:bg-indigo-900 transition-all font-medium\">🐧 리눅스 심층 가이드 (출력 해석 & 장애 진단) ➔</a>\n          </div>\n        </div>\n        <!-- Roadmap Level Indicator -->\n        <div class=\"grid grid-cols-5 gap-2 w-full lg:w-auto text-center text-xs shrink-0\">\n          <div class=\"p-2.5 rounded-lg bg-emerald-950/60 border border-emerald-500/30\">\n            <div class=\"font-bold text-emerald-400\">기초 L1</div>\n            <div class=\"text-[10px] text-slate-400 mt-0.5\">단일조작·점검</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-blue-950/60 border border-blue-500/30\">\n            <div class=\"font-bold text-blue-400\">기본 L2</div>\n            <div class=\"text-[10px] text-slate-400 mt-0.5\">파티션·컨테이너</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-purple-950/60 border border-purple-500/30\">\n            <div class=\"font-bold text-purple-400\">중급 L3</div>\n            <div class=\"text-[10px] text-slate-400 mt-0.5\">LVM·Dockerfile</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-amber-950/60 border border-amber-500/30\">\n            <div class=\"font-bold text-amber-400\">고급 L4</div>\n            <div class=\"text-[10px] text-slate-400 mt-0.5\">RAID·볼륨·Hub</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-rose-950/60 border border-rose-500/30\">\n            <div class=\"font-bold text-rose-400\">심화 L5</div>\n            <div class=\"text-[10px] text-slate-400 mt-0.5\">Compose·eBPF</div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Linux Guide Bridge Banner -->\n    <div class=\"mb-6 p-4 rounded-xl bg-gradient-to-r from-slate-950 via-slate-900 to-indigo-950/70 border border-indigo-900/60 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 shadow-lg\">\n      <div class=\"flex items-start sm:items-center gap-3.5\">\n        <div class=\"w-10 h-10 rounded-xl bg-indigo-950 border border-indigo-700/50 flex items-center justify-center text-xl shrink-0\">\n          🐧\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2 flex-wrap\">\n            <h3 class=\"text-sm font-bold text-white\">명령어 실행을 넘어 시스템 출력을 해석하고 장애를 추적하세요</h3>\n            <span class=\"text-[10px] px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-300 border border-indigo-500/30 font-semibold\">필수 연계 가이드</span>\n          </div>\n          <p class=\"text-xs text-slate-300 mt-1 leading-relaxed\">\n            <code>uptime</code>, <code>free -h -w</code>, <code>iostat</code>, <code>ss</code> 오독 방지 포인트와 서버 장애 증상별(CPU·디스크 100%·네트워크 단절) 단계적 진단 순서를 함께 제공합니다.\n          </p>\n        </div>\n      </div>\n      <a href=\"/study/linux\" class=\"px-4 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shrink-0 transition-all shadow-md shadow-indigo-500/20 whitespace-nowrap\">\n        🐧 리눅스 CLI 심층 가이드 보기 ➔\n      </a>\n    </div>\n\n    <!-- Sticky Filter & Search Toolbar -->\n    <section class=\"sticky top-14 z-40 bg-slate-950/95 backdrop-blur-md pt-3 pb-3 border-b border-slate-800 shadow-xl -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 mb-6\">\n      \n      <!-- Top Row: Search Input + View Mode Switcher + Clear Button -->\n      <div class=\"flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 mb-3\">\n        <!-- Search Input -->\n        <div class=\"relative flex-1 max-w-2xl\">\n          <span class=\"absolute left-3.5 top-2.5 text-slate-400 text-sm\">🔍</span>\n          <input type=\"text\" id=\"searchInput\" placeholder=\"명령어, 옵션, 키워드, 용어 뜻 검색 (docker, lvm, awk, parted, free)...\" \n                 class=\"w-full bg-slate-900 border border-slate-700 rounded-xl pl-10 pr-24 py-2 text-sm text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all shadow-inner\">\n          <div class=\"absolute right-2.5 top-2 flex items-center gap-1.5\">\n            <button id=\"clearSearchBtn\" class=\"hidden text-xs px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition-all\" title=\"검색어 지우기\">✕</button>\n            <span class=\"text-[10px] text-slate-500 font-mono bg-slate-800 px-1.5 py-0.5 rounded border border-slate-700\">⌘K</span>\n          </div>\n        </div>\n\n        <!-- View Mode Switcher & Counter -->\n        <div class=\"flex items-center justify-between md:justify-end gap-3 shrink-0\">\n          <div class=\"text-xs font-semibold text-slate-300\" id=\"itemCount\">총 114개 항목 표시 중</div>\n          \n          <div class=\"flex items-center bg-slate-900 p-1 rounded-xl border border-slate-800 text-xs\">\n            <button id=\"viewTableBtn\" class=\"px-3 py-1.5 rounded-lg text-slate-400 hover:text-white transition-all flex items-center gap-1.5\" title=\"한눈에 빠르게 훑어보는 컴팩트 목록 뷰\">\n              <span>📋</span> <span class=\"hidden sm:inline\">목록 요약 뷰</span>\n            </button>\n            <button id=\"viewCardBtn\" class=\"px-3 py-1.5 rounded-lg active-view text-white transition-all flex items-center gap-1.5\" title=\"상세 설명과 실행 구문이 포함된 카드 뷰\">\n              <span>🗂️</span> <span class=\"hidden sm:inline\">상세 카드 뷰</span>\n            </button>\n          </div>\n\n          <button id=\"resetAllBtn\" class=\"hidden text-xs px-2.5 py-1.5 rounded-lg bg-rose-950 text-rose-300 border border-rose-800/80 hover:bg-rose-900 transition-all\">\n            🔄 초기화\n          </button>\n        </div>\n      </div>\n\n      <!-- Middle Row: Category Tabs with Live Badges -->\n      <div class=\"flex items-center gap-1.5 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-slate-700 text-xs\" id=\"categoryTabs\">\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-blue-600 text-white flex items-center gap-1.5 shadow-md shadow-blue-600/20\" data-cat=\"all\">\n          <span>전체 보기</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-white/20 text-white font-bold\" id=\"badge-all\">114</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-cyan-950/80 text-cyan-300 border border-cyan-700/60 hover:bg-cyan-900/80 flex items-center gap-1.5\" data-cat=\"docker\">\n          <span>🐳 도커 & 컨테이너</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 font-bold\" id=\"badge-docker\">30</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-emerald-950/80 text-emerald-300 border border-emerald-700/60 hover:bg-emerald-900/80 flex items-center gap-1.5\" data-cat=\"disk\">\n          <span>💾 스토리지 & 디스크</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 font-bold\" id=\"badge-disk\">27</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"process\">\n          <span>⚙️ 시스템 & 프로세스</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-process\">15</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"sec\">\n          <span>🔒 권한 & 보안 & 계정</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-sec\">11</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"file\">\n          <span>📁 파일 & 디렉토리</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-file\">9</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"net\">\n          <span>🌐 네트워크 & 소켓</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-net\">8</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"text\">\n          <span>📜 텍스트 & 로그 & 셸</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-text\">6</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5\" data-cat=\"sre\">\n          <span>🔥 SRE & eBPF 진단</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-slate-700 text-slate-300 font-bold\" id=\"badge-sre\">3</span>\n        </button>\n        <button class=\"cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-indigo-900/60 text-indigo-300 border border-indigo-500/30 hover:bg-indigo-800/60 flex items-center gap-1.5\" data-cat=\"scenario\">\n          <span>💼 실무 시나리오</span>\n          <span class=\"px-1.5 py-0.5 rounded-full text-[10px] bg-indigo-500/20 text-indigo-300 font-bold\" id=\"badge-scenario\">5</span>\n        </button>\n      </div>\n\n      <!-- Bottom Row: Subtag Chips & Level Pills -->\n      <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2.5 pt-2 border-t border-slate-800/80 text-xs\">\n        <!-- Subtag Chips (Dynamic per category) -->\n        <div class=\"flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0\" id=\"subtagContainer\">\n          <span class=\"text-slate-400 font-semibold shrink-0\">추천 키워드:</span>\n          <div id=\"subtagChips\" class=\"flex items-center gap-1.5 flex-wrap\">\n            <!-- Rendered by JS -->\n          </div>\n        </div>\n\n        <!-- Level Pills -->\n        <div class=\"flex items-center gap-1 shrink-0\">\n          <span class=\"text-slate-400 font-semibold mr-1 hidden lg:inline\">난이도:</span>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-slate-800 text-slate-300 hover:bg-slate-700 active-lvl\" data-lvl=\"all\">전체</button>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800\" data-lvl=\"L1\">L1</button>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800\" data-lvl=\"L2\">L2</button>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-purple-950 text-purple-300 border border-purple-800\" data-lvl=\"L3\">L3</button>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-amber-950 text-amber-300 border border-amber-800\" data-lvl=\"L4\">L4</button>\n          <button class=\"lvl-btn px-2 py-1 rounded bg-rose-950 text-rose-300 border border-rose-800\" data-lvl=\"L5\">L5</button>\n        </div>\n      </div>\n\n    </section>\n\n    <!-- Main Dynamic Display Containers -->\n    \n    <!-- 1. Detail Card View Grid -->\n    <div id=\"cardsGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n      <!-- Dynamic Content Rendered via JS -->\n    </div>\n\n    <!-- 2. Compact Table View Container -->\n    <div id=\"tableView\" class=\"hidden\">\n      <div class=\"rounded-xl border border-slate-800 bg-slate-950 overflow-hidden shadow-2xl\">\n        <div class=\"overflow-x-auto\">\n          <table class=\"w-full text-left text-xs border-collapse\">\n            <thead>\n              <tr class=\"border-b border-slate-800 bg-slate-900/90 text-slate-300\">\n                <th class=\"py-3 px-3.5 font-bold w-28\">분야 / 레벨</th>\n                <th class=\"py-3 px-3.5 font-bold w-64 sm:w-72\">명령어 & 실행 구문</th>\n                <th class=\"py-3 px-3.5 font-bold\">핵심 목적 & 실무 시나리오</th>\n                <th class=\"py-3 px-3.5 font-bold w-80 lg:w-96 text-amber-400\">💡 용어 설명 (어원·개념)</th>\n                <th class=\"py-3 px-3.5 font-bold w-16 text-center\">복사</th>\n              </tr>\n            </thead>\n            <tbody id=\"tableBody\" class=\"divide-y divide-slate-800/60 text-slate-300 font-sans\">\n              <!-- Dynamic Rows Rendered via JS -->\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <!-- Modern vs Legacy Comparative Section -->\n    <section class=\"mt-14 pt-8 border-t border-slate-800\">\n      <div class=\"flex items-center gap-3 mb-6\">\n        <span class=\"text-2xl\">⚡</span>\n        <div>\n          <h3 class=\"text-lg font-bold text-white\">현대적 인프라 치환 맵 (Legacy ➡️ Modern Cloud Architecture)</h3>\n          <p class=\"text-xs text-slate-400\">구식 리눅스 도구와 레거시 가상화 기술을 최신 고성능 도커 및 클라우드 엔지니어링 표준으로 전환하세요. 상세 비교 이유는 <a href=\"/study/linux#modern\" class=\"text-blue-400 hover:underline font-semibold\">🐧 리눅스 CLI 심층 가이드</a>에서 확인하실 수 있습니다.</p>\n        </div>\n      </div>\n      <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n        <!-- 1. Docker vs VM -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800 hover:border-cyan-500/50 transition-colors\">\n          <div class=\"text-xs text-rose-400 line-through\">Type-1/2 가상머신 (Guest OS)</div>\n          <div class=\"text-sm font-bold text-cyan-400 font-mono mt-1\">도커 컨테이너 (OCI / Cgroups)</div>\n          <p class=\"text-xs text-slate-400 mt-2\">무거운 게스트 OS 부팅과 하이퍼바이저 오버헤드를 완전히 제거하고, 커널 네임스페이스 격리로 밀리초 단위 초고속 기동.</p>\n        </div>\n        <!-- 2. MBR vs GPT -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800 hover:border-emerald-500/50 transition-colors\">\n          <div class=\"text-xs text-rose-400 line-through\">MBR 파티션 (fdisk / 2TB 한계)</div>\n          <div class=\"text-sm font-bold text-emerald-400 font-mono mt-1\">GPT 파티션 (parted / gdisk)</div>\n          <p class=\"text-xs text-slate-400 mt-2\">2TiB 및 4개 주 파티션 제한을 극복하고, 최대 8ZiB 용량과 128개 파티션, 헤더/백업 CRC32 복원력 제공.</p>\n        </div>\n        <!-- 3. Fixed vs LVM -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800 hover:border-purple-500/50 transition-colors\">\n          <div class=\"text-xs text-rose-400 line-through\">고정 하드웨어 물리 파티션</div>\n          <div class=\"text-sm font-bold text-purple-400 font-mono mt-1\">LVM (PV ➔ VG ➔ LV)</div>\n          <p class=\"text-xs text-slate-400 mt-2\">물리 디스크 경계를 허물어 거대한 스토리지 풀(VG)을 형성하고, 운영 중 무중단 온라인 볼륨 확장(lvextend)과 COW 스냅샷 지원.</p>\n        </div>\n        <!-- 4. Manual container vs Compose -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800 hover:border-blue-500/50 transition-colors\">\n          <div class=\"text-xs text-rose-400 line-through\">단일 docker run 수동 스크립트</div>\n          <div class=\"text-sm font-bold text-blue-400 font-mono mt-1\">Docker Compose (IaC 선언형)</div>\n          <p class=\"text-xs text-slate-400 mt-2\">Web, WAS, DB, Cache 등 멀티 컨테이너와 네트워크, 볼륨 의존성을 단일 YAML 코드로 문서화하고 원클릭 일괄 제어.</p>\n        </div>\n        <!-- 5. ifconfig vs ip -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800\">\n          <div class=\"text-xs text-rose-400 line-through\">ifconfig</div>\n          <div class=\"text-sm font-bold text-emerald-400 font-mono mt-1\">ip addr / ip link / ip route</div>\n          <p class=\"text-xs text-slate-400 mt-2\">net-tools 노후화로 인한 iproute2 표준 전환. 가상 인터페이스 및 터널링 완벽 지원.</p>\n        </div>\n        <!-- 6. netstat vs ss -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800\">\n          <div class=\"text-xs text-rose-400 line-through\">netstat -tlpn</div>\n          <div class=\"text-sm font-bold text-emerald-400 font-mono mt-1\">ss -tlpn</div>\n          <p class=\"text-xs text-slate-400 mt-2\">수만 개의 TCP 연결 상태를 커널 소켓 다이어그램에서 직접 조회하여 100배 빠른 속도.</p>\n        </div>\n        <!-- 7. tail syslog vs journalctl -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800\">\n          <div class=\"text-xs text-rose-400 line-through\">tail -f /var/log/syslog</div>\n          <div class=\"text-sm font-bold text-emerald-400 font-mono mt-1\">journalctl -u {svc} -f</div>\n          <p class=\"text-xs text-slate-400 mt-2\">systemd 통합 바이너리 저널. 부팅 시점별, 유닛별, 심각도별 즉시 인덱싱 필터링 및 디스크 영구 저장.</p>\n        </div>\n        <!-- 8. service vs systemctl -->\n        <div class=\"p-4 rounded-xl bg-slate-950 border border-slate-800\">\n          <div class=\"text-xs text-rose-400 line-through\">service {svc} start</div>\n          <div class=\"text-sm font-bold text-emerald-400 font-mono mt-1\">systemctl start {svc}</div>\n          <p class=\"text-xs text-slate-400 mt-2\">SysV Init 스크립트 대신 cgroups 기반 프로세스 트리 추적 및 표준 의존성 관리.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- Architecture & Syntax Anatomy Explainer Box -->\n    <section class=\"mt-12 space-y-6\">\n      \n      <!-- 1. Dockerfile Anatomy -->\n      <div class=\"p-6 rounded-2xl bg-slate-950 border border-cyan-900/60 shadow-lg\">\n        <h3 class=\"text-md font-bold text-white flex items-center gap-2 mb-3\">\n          <span class=\"text-cyan-400\">🐳</span>\n          <span>도커파일 빌드 구조 분해기 (Dockerfile Syntax Anatomy)</span>\n        </h3>\n        <p class=\"text-xs text-slate-400 mb-4\">강의 실습에서 다룬 Nginx 웹서버 패키징 및 포그라운드 실행(daemon off) 핵심 원리입니다.</p>\n        <div class=\"bg-slate-900 p-4 rounded-xl font-mono text-sm border border-slate-800 overflow-x-auto text-slate-200\">\n          <span class=\"text-purple-400 font-bold\">FROM</span> <span class=\"text-cyan-300\">ubuntu</span><br>\n          <span class=\"text-purple-400 font-bold\">RUN</span> <span class=\"text-yellow-300\">apt update &amp;&amp; apt install -y nginx</span><br>\n          <span class=\"text-purple-400 font-bold\">COPY</span> <span class=\"text-emerald-300\">index.html /var/www/html/</span><br>\n          <span class=\"text-purple-400 font-bold\">CMD</span> <span class=\"text-blue-300\">nginx -g \"daemon off;\"</span>\n        </div>\n        <div class=\"grid grid-cols-1 sm:grid-cols-4 gap-3 mt-4 text-xs\">\n          <div class=\"p-3 rounded-lg bg-slate-900/90 border border-slate-800\">\n            <div class=\"font-bold text-purple-400\">1. FROM ubuntu</div>\n            <div class=\"text-slate-400 mt-1\">컨테이너 이미지의 기반이 되는 베이스 OS 레이어를 정의 (도커 허브 공식 이미지 사용)</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900/90 border border-slate-800\">\n            <div class=\"font-bold text-yellow-400\">2. RUN apt install</div>\n            <div class=\"text-slate-400 mt-1\">이미지 빌드 시점에 Nginx 및 필수 패키지를 설치하고 새로운 읽기 전용 이미지 레이어로 커밋</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900/90 border border-slate-800\">\n            <div class=\"font-bold text-emerald-400\">3. COPY index.html</div>\n            <div class=\"text-slate-400 mt-1\">호스트 파일시스템의 웹 리소스를 컨테이너 내부 웹 루트 디렉토리(/var/www/html/)로 직접 주입</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900/90 border border-slate-800\">\n            <div class=\"font-bold text-blue-400\">4. CMD daemon off;</div>\n            <div class=\"text-slate-400 mt-1\">Nginx를 백그라운드가 아닌 포그라운드로 실행하여 PID 1 프로세스가 유지되도록 강제 (컨테이너 종료 방지)</div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 2. LVM Storage Architecture -->\n      <div class=\"p-6 rounded-2xl bg-slate-950 border border-emerald-900/60 shadow-lg\">\n        <h3 class=\"text-md font-bold text-white flex items-center gap-2 mb-3\">\n          <span class=\"text-emerald-400\">💾</span>\n          <span>스토리지 LVM 3계층 아키텍처 (Physical ➡️ Volume Group ➡️ Logical Volume)</span>\n        </h3>\n        <p class=\"text-xs text-slate-400 mb-4\">강의 0908 실습: 디스크 파티션부터 무중단 파일시스템 확장까지의 논리 계층 흐름도입니다.</p>\n        <div class=\"grid grid-cols-1 sm:grid-cols-4 gap-3 text-xs\">\n          <div class=\"p-3 rounded-lg bg-slate-900 border border-emerald-900/40\">\n            <span class=\"text-[10px] font-mono uppercase text-emerald-400 font-bold\">1단계: 물리 볼륨 (PV)</span>\n            <div class=\"font-bold text-slate-200 mt-1 font-mono\">pvcreate /dev/nvme0n2p1</div>\n            <div class=\"text-slate-400 mt-1 leading-relaxed\">물리 디스크나 파티션을 LVM이 관리할 수 있는 기본 물리 볼륨(Physical Volume)으로 초기화합니다.</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900 border border-emerald-900/40\">\n            <span class=\"text-[10px] font-mono uppercase text-emerald-400 font-bold\">2단계: 볼륨 그룹 (VG)</span>\n            <div class=\"font-bold text-slate-200 mt-1 font-mono\">vgcreate vg01 /dev/...</div>\n            <div class=\"text-slate-400 mt-1 leading-relaxed\">여러 PV를 하나로 결합하여 거대한 가상 스토리지 풀(Volume Group)을 형성하고 용량을 통합합니다.</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900 border border-emerald-900/40\">\n            <span class=\"text-[10px] font-mono uppercase text-emerald-400 font-bold\">3단계: 논리 볼륨 (LV)</span>\n            <div class=\"font-bold text-slate-200 mt-1 font-mono\">lvcreate -L 1G -n data vg01</div>\n            <div class=\"text-slate-400 mt-1 leading-relaxed\">VG 풀에서 필요한 크기만큼 논리 볼륨(Logical Volume)을 동적으로 분할 할당합니다.</div>\n          </div>\n          <div class=\"p-3 rounded-lg bg-slate-900 border border-emerald-900/40\">\n            <span class=\"text-[10px] font-mono uppercase text-emerald-400 font-bold\">4단계: 포맷 &amp; 무중단 확장</span>\n            <div class=\"font-bold text-slate-200 mt-1 font-mono\">xfs_growfs / mount</div>\n            <div class=\"text-slate-400 mt-1 leading-relaxed\">XFS/ext4 포맷 및 마운트 후, 용량 부족 시 <code>lvextend</code> 및 <code>xfs_growfs</code>로 무중단 온라인 증설합니다.</div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 3. Pipeline Anatomy -->\n      <div class=\"p-6 rounded-2xl bg-slate-950 border border-slate-800 shadow-lg\">\n        <h3 class=\"text-md font-bold text-white flex items-center gap-2 mb-3\">\n          <span class=\"text-yellow-400\">🔍</span>\n          <span>파이프라인 문법 분해기 (Linux Pipeline Anatomy)</span>\n        </h3>\n        <p class=\"text-xs text-slate-400 mb-4\">리눅스 표준 스트림을 결합하여 500 에러 최다 발생 URL을 추출하는 실무 데이터 파이프라인입니다. 토큰별 상세 동작 분석은 <a href=\"/study/linux#pipeline\" class=\"text-yellow-400 hover:underline font-semibold\">🐧 리눅스 가이드 파이프라인 해부</a>에 연동되어 있습니다.</p>\n        <div class=\"bg-slate-900 p-4 rounded-xl font-mono text-sm border border-slate-800 overflow-x-auto text-slate-200\">\n          <span class=\"text-blue-400 font-bold\">awk</span> <span class=\"text-yellow-400\">'$9 == \"500\" {print $7}'</span> access.log <span class=\"text-slate-500\">|</span> <span class=\"text-purple-400 font-bold\">sort</span> <span class=\"text-slate-500\">|</span> <span class=\"text-emerald-400 font-bold\">uniq -c</span> <span class=\"text-slate-500\">|</span> <span class=\"text-purple-400 font-bold\">sort -nr</span> <span class=\"text-slate-500\">|</span> <span class=\"text-rose-400 font-bold\">head -n 5</span>\n        </div>\n        <div class=\"grid grid-cols-1 sm:grid-cols-5 gap-3 mt-4 text-xs\">\n          <div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800\">\n            <div class=\"font-bold text-blue-400\">1. awk '$9 == \"500\"'</div>\n            <div class=\"text-slate-400 mt-1\">9번째 컬럼(HTTP 상태코드)이 500인 행의 7번째 컬럼(URL 경로)만 추출</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800\">\n            <div class=\"font-bold text-purple-400\">2. sort</div>\n            <div class=\"text-slate-400 mt-1\">동일한 URL끼리 인접하도록 사전순 1차 정렬 (uniq 필수 전제조건)</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800\">\n            <div class=\"font-bold text-emerald-400\">3. uniq -c</div>\n            <div class=\"text-slate-400 mt-1\">연속된 중복 라인을 하나로 합치고 발생 빈도 카운트를 앞에 부착</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800\">\n            <div class=\"font-bold text-purple-400\">4. sort -nr</div>\n            <div class=\"text-slate-400 mt-1\">앞의 발생 빈도 숫자(-n)를 기준으로 내림차순(-r: 큰 숫자 순) 재정렬</div>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-slate-900 border border-slate-800\">\n            <div class=\"font-bold text-rose-400\">5. head -n 5</div>\n            <div class=\"text-slate-400 mt-1\">가장 장애를 많이 유발한 최상위 Top 5 문제 엔드포인트만 최종 출력</div>\n          </div>\n        </div>\n      </div>\n\n    </section>\n\n  </main>\n\n  <!-- Toast Notification -->\n  <div id=\"toast\" class=\"fixed bottom-6 right-6 bg-blue-600 text-white px-4 py-2.5 rounded-xl shadow-2xl text-xs font-semibold transform translate-y-20 opacity-0 transition-all duration-300 flex items-center gap-2 z-50\">\n    <span>✓</span> <span id=\"toastMsg\">클립보드에 복사되었습니다!</span>\n  </div>\n\n  <script>\n    const data = [\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"Docker 원클릭 설치 & 소켓 권한 부여\",\n        \"cmd\": \"curl -s https://get.docker.com | sh && sudo usermod -aG docker $USER && newgrp docker\",\n        \"desc\": \"공식 자동 설치 스크립트로 Docker Engine을 설치하고 일반 사용자 계정을 docker 그룹에 추가하여 sudo 없이 실행할 수 있도록 권한을 부여합니다.\",\n        \"scenario\": \"Ubuntu/Debian 리눅스 인프라 환경에서 도커 소켓(/var/run/docker.sock) 접근 권한 오류 없이 도커 런타임 초기 환경 구축\",\n        \"tags\": [\n            \"Docker\",\n            \"설치\",\n            \"usermod\",\n            \"소켓권한\",\n            \"초기설정\"\n        ],\n        \"abbr\": \"usermod(User Modify: 사용자 정보 수정) · newgrp(New Group: 새 그룹 즉시 적용) — 관리자 권한(sudo) 없이도 일반 사용자가 도커 소켓(/var/run/docker.sock)을 통해 도커 엔진을 직접 제어할 수 있도록 docker 그룹 권한을 부여하고 즉시 갱신\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"docker run 대화형 컨테이너 실행\",\n        \"cmd\": \"docker run -it --name hello-ubuntu ubuntu bash\",\n        \"desc\": \"Ubuntu 최신 베이스 이미지를 원격 레지스트리에서 받아 대화형(-it) 터미널 셸을 즉시 구동합니다. 종료 시 컨테이너 상태는 보존됩니다.\",\n        \"scenario\": \"호스트 환경을 오염시키지 않고 순수 격리된 리눅스 샌드박스에서 패키지 설치 및 환경 테스트\",\n        \"tags\": [\n            \"Docker\",\n            \"run\",\n            \"ubuntu\",\n            \"대화형\",\n            \"컨테이너\"\n        ],\n        \"abbr\": \"-i(Interactive: 표준입력 유지) · -t(TTY: 가상 터미널 할당) — 호스트 터미널에서 격리된 컨테이너 내부의 리눅스 셸(bash)로 직접 키보드 입력을 전달하고 화면 출력을 실시간으로 대화형 조작\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"컨테이너 목록 조회 & 정리 (ps, rm, rmi)\",\n        \"cmd\": \"docker ps -a && docker stop web-app && docker rm web-app && docker rmi nginx:latest\",\n        \"desc\": \"실행 중 및 중지된 전체 컨테이너(-a)를 조회하고, 지정 컨테이너를 정상 중지 및 삭제한 뒤 미사용 이미지를 삭제합니다.\",\n        \"scenario\": \"테스트가 완료된 컨테이너와 캐시 이미지를 정리하여 호스트 리소스 회수 및 네이밍 충돌 방지\",\n        \"tags\": [\n            \"Docker\",\n            \"ps\",\n            \"stop\",\n            \"rm\",\n            \"생명주기\"\n        ],\n        \"abbr\": \"ps(Process Status: 프로세스 상태) · rm(Remove: 컨테이너 삭제) · rmi(Remove Image: 이미지 삭제) — 실행 중이거나 중지된 컨테이너 목록을 확인하고, 생명주기가 끝난 컨테이너 인스턴스와 불필요한 기본 이미지를 완전히 제거하여 디스크 용량 회수\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"포트 포워딩 웹 컨테이너 백그라운드 구동 (-p, -d)\",\n        \"cmd\": \"docker run -d -p 81:80 --name web-server nginx\",\n        \"desc\": \"호스트의 81번 포트를 컨테이너 내부 Nginx 기본 80번 포트로 매핑(-p)하고 백그라운드 데몬(-d)으로 실행합니다.\",\n        \"scenario\": \"호스트 IP와 지정 포트(예: 192.168.x.x:81)로 외부 클라이언트가 직접 웹 서비스에 접근할 수 있도록 포트 바인딩 배포\",\n        \"tags\": [\n            \"Docker\",\n            \"포트포워딩\",\n            \"Nginx\",\n            \"백그라운드\",\n            \"포트바인딩\"\n        ],\n        \"abbr\": \"-d(Detached: 터미널과 분리되어 백그라운드 상주 실행) · -p(Publish: 포트 개방/바인딩) — 터미널을 닫아도 웹서버가 종료되지 않도록 백그라운드로 띄우고, 외부 클라이언트가 호스트 IP:포트로 컨테이너 내부 웹 서비스에 접속할 수 있도록 포트 포워딩 연결\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker exec & 포그라운드 데몬 제어 (daemon off)\",\n        \"cmd\": \"docker exec -it web-server bash -c \\\"nginx -g 'daemon off;'\\\"\",\n        \"desc\": \"실행 중인 컨테이너에 접속하여 명령을 수행하며, Nginx를 백그라운드가 아닌 포그라운드(daemon off) 모드로 기동하여 PID 1 유지 원리를 실습합니다.\",\n        \"scenario\": \"컨테이너 내부 서비스가 백그라운드로 전환되면서 컨테이너가 즉시 종료(Exit 0)되는 현상 방지 및 수동 서비스 디버깅\",\n        \"tags\": [\n            \"Docker\",\n            \"exec\",\n            \"daemon_off\",\n            \"PID1\",\n            \"디버깅\"\n        ],\n        \"abbr\": \"exec(Execute: 실행 중인 컨테이너에 명령 실행) · daemon off(백그라운드 비활성화) — 도커는 1번 메인 프로세스(PID 1)가 끝나면 컨테이너가 즉시 꺼지므로, Nginx가 백그라운드로 숨지 않고 화면 앞에 머물도록 강제하여 컨테이너 생존을 유지하는 원리\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"컨테이너 내부 웹 리소스 수정 & 핫픽스\",\n        \"cmd\": \"docker exec -it web-server bash -c \\\"echo 'This is KT-CI5 HOME page' > /var/www/html/index.nginx-debian.html\\\"\",\n        \"desc\": \"컨테이너 내부 셸로 진입하여 기본 웹 루트 디렉토리(/var/www/html)의 index 문서를 덮어쓰고 실시간 반영을 확인합니다.\",\n        \"scenario\": \"컨테이너 재빌드 없이 내부 정적 웹페이지 내용 긴급 수정 및 실시간 웹 서비스 반영 테스트\",\n        \"tags\": [\n            \"Docker\",\n            \"exec\",\n            \"웹수정\",\n            \"HTML\",\n            \"실시간반영\"\n        ],\n        \"abbr\": \"exec(Execute: 명령 실행) — 컨테이너 이미지를 다시 빌드하거나 서비스를 재시작하지 않고도, 가동 중인 컨테이너 내부 파일시스템(/var/www/html)으로 직접 침투하여 웹 문서나 설정 파일을 실시간 즉시 수정(핫픽스)\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"컨테이너 가상 사설 IP 조회 & 통신 검증\",\n        \"cmd\": \"docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' web-server && curl $(docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' web-server)\",\n        \"desc\": \"도커 기본 브릿지(docker0)가 컨테이너에 동적으로 할당한 가상 사설 IP(예: 172.17.0.2)를 조회하고 curl로 HTTP 응답을 검증합니다.\",\n        \"scenario\": \"포트 포워딩 없이 호스트 내부 도커 가상 인터페이스 대역 통신 무결성 및 라우팅 상태 점검\",\n        \"tags\": [\n            \"Docker\",\n            \"inspect\",\n            \"가상IP\",\n            \"curl\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"inspect(세부 메타데이터 검사) — 도커 가상 스위치(docker0)가 컨테이너에 동적으로 발급한 사설 네트워크 IP 주소를 확인하고, 호스트 내부에서 curl을 통해 포트 바인딩 없이도 직접 통신이 되는지 네트워크 정합성 검증\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"Dockerfile 작성 및 커스텀 Nginx 이미지 빌드\",\n        \"cmd\": \"cat << 'EOF' > Dockerfile\\nFROM ubuntu\\nRUN apt update && apt install -y nginx\\nCOPY index.html /var/www/html/\\nCMD nginx -g \\\"daemon off;\\\"\\nEOF\\ndocker build -t test:nginx .\",\n        \"desc\": \"Ubuntu 베이스 이미지에 Nginx 설치, 커스텀 index.html 복사, 포그라운드 실행 CMD를 정의한 Dockerfile을 작성하고 test:nginx 태그로 빌드합니다.\",\n        \"scenario\": \"인프라 설정을 코드로 문서화(IaC)하여 동일한 환경을 재현 가능하도록 커스텀 웹 애플리케이션 컨테이너 패키징\",\n        \"tags\": [\n            \"Dockerfile\",\n            \"docker_build\",\n            \"IaC\",\n            \"Nginx\",\n            \"이미지제작\"\n        ],\n        \"abbr\": \"FROM(기반 베이스 이미지 지정) · RUN(빌드 시 패키지 설치 실행) · COPY(호스트 파일을 이미지 안으로 복사) · CMD(컨테이너 기동 시 실행할 기본 명령어) — 코드형 인프라(IaC)로 소프트웨어 설치와 환경 구성을 하나의 레시피 문서로 규격화하여 동일한 이미지 빌드\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"Docker Hub 태깅 & 원격 레지스트리 푸시\",\n        \"cmd\": \"docker tag test:nginx docker.io/$DOCKER_USER/test:nginx && docker login && docker push docker.io/$DOCKER_USER/test:nginx\",\n        \"desc\": \"로컬에서 빌드한 이미지를 본인의 Docker Hub 계정 네임스페이스로 태그 지정하고, 브라우저/CLI 로그인 후 중앙 레지스트리에 푸시합니다.\",\n        \"scenario\": \"팀원 간 이미지 공유 및 클라우드 인스턴스로의 컨테이너 이미지 원격 배포 파이프라인\",\n        \"tags\": [\n            \"DockerHub\",\n            \"tag\",\n            \"push\",\n            \"login\",\n            \"레지스트리\"\n        ],\n        \"abbr\": \"tag(이미지에 식별 이름/버전 달기) · push(원격 저장소 업로드) — 로컬에서 빌드한 이미지를 본인의 원격 도커 허브 계정 네임스페이스와 버전 태그로 연결하고, 인터넷을 통해 중앙 이미지 저장소(Registry)로 업로드\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"팀원(짝꿍) 이미지 풀 & 포트 분리 상호 배포 검증\",\n        \"cmd\": \"docker run -d -p 82:80 --name peer-web $PEER_USER/test:nginx && curl -I http://localhost:82\",\n        \"desc\": \"Docker Hub에 올라온 동료의 이미지를 받아 충돌 없는 82번 포트로 배포하고 curl HTTP 응답 헤더(200 OK)를 교차 검증합니다.\",\n        \"scenario\": \"실습 파트너와 서로 만든 컨테이너 이미지를 교차 배포하여 네트워크 포트 격리 및 의존성 독립성 확인\",\n        \"tags\": [\n            \"Docker\",\n            \"협업\",\n            \"교차검증\",\n            \"포트격리\",\n            \"팀배포\"\n        ],\n        \"abbr\": \"pull(원격 이미지 내려받기) & run(컨테이너 실행) — 동료가 도커 허브에 올린 원격 이미지를 그대로 받아와서 충돌 없는 다른 포트(82번)로 띄워보고, 동일한 웹 애플리케이션이 서로 다른 환경에서도 완벽히 동작하는지 검증\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"호스트 볼륨 바인드 마운트 (데이터 영속성)\",\n        \"cmd\": \"docker run -d -p 8080:80 -v /opt/webdata:/var/www/html:ro --name web-vol nginx\",\n        \"desc\": \"호스트 파일시스템(/opt/webdata)을 컨테이너 내부 웹 경로에 읽기 전용(:ro) 바인드 마운트하여 컨테이너 삭제 시에도 데이터를 영구 보존합니다.\",\n        \"scenario\": \"DB 데이터, 로그, 업로드 정적 파일의 무유실 영속성 보장 및 무중단 웹 소스코드 핫스왑\",\n        \"tags\": [\n            \"Docker\",\n            \"볼륨\",\n            \"마운트\",\n            \"데이터영속성\",\n            \"바인드마운트\"\n        ],\n        \"abbr\": \"-v(Volume: 저장소 연결/마운트) · :ro(Read Only: 읽기 전용) — 컨테이너는 삭제되면 내부 데이터가 모두 날아가므로, 호스트 디렉토리를 컨테이너 내부에 직접 연결(마운트)하여 컨테이너가 꺼져도 데이터가 영구 보존되도록 보장\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"사용자 정의 브릿지 네트워크 생성 & 컨테이너 DNS 통신\",\n        \"cmd\": \"docker network create --driver bridge app-net && docker run -d --net app-net --name backend-api my-api\",\n        \"desc\": \"기본 bridge 네트워크와 격리된 커스텀 브릿지 네트워크를 생성하고 컨테이너를 연결하여 IP 대신 컨테이너 이름(DNS)으로 상호 호출을 활성화합니다.\",\n        \"scenario\": \"마이크로서비스 아키텍처(MSA)에서 동적 사설 IP 변경에 영향받지 않는 안정적인 컨테이너 간 서비스 디스커버리\",\n        \"tags\": [\n            \"Docker\",\n            \"network\",\n            \"브릿지\",\n            \"DNS통신\",\n            \"MSA\"\n        ],\n        \"abbr\": \"bridge(가상 네트워크 스위치) · DNS(도메인 이름 해석) — 도커 기본 네트워크와 분리된 커스텀 가상 사설망을 만들어 컨테이너들을 묶으면, 동적으로 바뀌는 IP 주소 대신 '컨테이너 이름'만으로 서로 통신할 수 있는 내장 DNS 통신 지원\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"Docker Compose 다중 컨테이너 선언형 오케스트레이션\",\n        \"cmd\": \"docker compose up -d && docker compose ps && docker compose logs -f web\",\n        \"desc\": \"docker-compose.yml 파일에 선언된 웹서버, 백엔드 API, 데이터베이스, 네트워크, 볼륨 스택을 원클릭으로 일괄 기동하고 상태를 추적합니다.\",\n        \"scenario\": \"복잡한 멀티 티어(Web-WAS-DB) 애플리케이션의 개발/스테이징/운영 환경 단일 코드로 신속 표준 배포\",\n        \"tags\": [\n            \"Compose\",\n            \"오케스트레이션\",\n            \"다중컨테이너\",\n            \"YAML\",\n            \"스택배포\"\n        ],\n        \"abbr\": \"compose(구성하다/조립하다) · up(스택 기동) · -d(백그라운드) — 웹서버, API 백엔드, 데이터베이스 등 복잡하게 얽힌 여러 컨테이너들을 하나의 YAML 파일에 정의하고, 단 한 번의 명령으로 네트워크와 볼륨까지 일괄 자동 배포\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"도커 디스크 사용량 분석 및 가비지 컬렉션 (prune)\",\n        \"cmd\": \"docker system df && docker system prune -af --volumes\",\n        \"desc\": \"이미지, 컨테이너, 볼륨, 빌드 캐시가 사용하는 실제 디스크 용량을 점검하고, 모든 미사용 자원을 강제(-af) 일괄 삭제하여 용량을 확보합니다.\",\n        \"scenario\": \"CI/CD 빌드 머신이나 개발 서버에서 찌꺼기 이미지와 레이어 누적으로 인한 Disk Full 장애 긴급 해소\",\n        \"tags\": [\n            \"Docker\",\n            \"system_prune\",\n            \"용량점검\",\n            \"가비지컬렉션\",\n            \"디스크정리\"\n        ],\n        \"abbr\": \"df(Disk Free: 용량 점검) · prune(가지치기/미사용 자원 정리) — 도커 컨테이너, 빌드 캐시, 미사용 이미지가 차지하는 디스크 공간을 분석하고, 찌꺼기 자원들을 한 번에 안전하게 삭제하여 디스크 풀(Disk Full) 장애를 긴급 해소\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"lsblk 디스크 블록 장치 상세 일람\",\n        \"cmd\": \"lsblk -o NAME,MAJ:MIN,RM,SIZE,RO,TYPE,MOUNTPOINTS,FSTYPE,UUID\",\n        \"desc\": \"물리 디스크(nvme, sda 등), 파티션, LVM 논리 볼륨, 마운트 지점, 파일시스템 종류 및 UUID 정보를 계층 트리 구조로 일람합니다.\",\n        \"scenario\": \"신규 디스크 장착 직후 블록 장치 인식 여부 및 기존 파티션/마운트 매핑 상태 1차 점검\",\n        \"tags\": [\n            \"디스크\",\n            \"lsblk\",\n            \"블록장치\",\n            \"UUID\",\n            \"파일시스템\"\n        ],\n        \"abbr\": \"lsblk(List Block Devices: 블록 장치 목록) — 하드디스크, SSD, NVMe, 파티션 등 데이터를 블록 단위로 읽고 쓰는 모든 물리 저장 장치와 마운트 지점을 한눈에 알아보기 쉽게 계층 트리 구조로 출력\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"df -h 파일시스템 여유 용량 점검\",\n        \"cmd\": \"df -h -T\",\n        \"desc\": \"마운트된 모든 파일시스템의 전체 크기, 사용량, 남은 공간(GB 단위) 및 파일시스템 타입(ext4, xfs)을 확인합니다.\",\n        \"scenario\": \"루트 파티션(/) 및 데이터 마운트 지점의 스토리지 용량 고갈 여부 실시간 점검\",\n        \"tags\": [\n            \"용량\",\n            \"df\",\n            \"스토리지\",\n            \"디스크사용량\"\n        ],\n        \"abbr\": \"df(Disk Free: 디스크 여유 공간) — 마운트된 모든 파티션의 전체 크기, 실제 사용량, 남아있는 여유 용량(Free)을 사람이 읽기 편한 단위(-h: GB, MB)와 파일시스템 종류(-T: xfs, ext4)로 확인\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"parted GPT 대용량 파티션 생성 (2TB+ 지원)\",\n        \"cmd\": \"parted -s /dev/nvme0n2 mklabel gpt mkpart primary xfs 1MiB 500MiB print\",\n        \"desc\": \"GNU parted 비대화식(-s) 명령으로 MBR 한계를 넘는 표준 GPT 레이블을 생성하고 500MiB 크기의 파티션을 즉시 생성합니다.\",\n        \"scenario\": \"2TB 초과 고성능 NVMe/SSD 디스크의 표준 GPT 파티셔닝 및 클라우드 가상 디스크 볼륨 초기화\",\n        \"tags\": [\n            \"parted\",\n            \"GPT\",\n            \"파티션\",\n            \"NVMe\",\n            \"블록장치\"\n        ],\n        \"abbr\": \"parted(Partition Editor: 파티션 분할 편집기) · GPT(GUID Partition Table: 2TB 한계를 넘는 최신 파티션 규격) — 구형 MBR의 2TB 용량 한계를 극복하고 대용량 NVMe/SSD 디스크를 빠르고 유연하게 구획 분할\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"mkfs.xfs / mkfs.ext4 파일시스템 포맷\",\n        \"cmd\": \"mkfs.xfs -f /dev/nvme0n2p1 && mkfs.ext4 -F /dev/nvme0n2p2\",\n        \"desc\": \"생성된 파티션에 최신 대용량 고성능 엔터프라이즈 표준 XFS 및 전통적인 ext4 파일시스템을 강제(-f, -F) 생성합니다.\",\n        \"scenario\": \"원시(Raw) 파티션을 운영체제가 파일과 디렉토리를 기록할 수 있는 파일시스템 구조로 포맷\",\n        \"tags\": [\n            \"mkfs\",\n            \"XFS\",\n            \"ext4\",\n            \"파일시스템\",\n            \"포맷\"\n        ],\n        \"abbr\": \"mkfs(Make File System: 파일시스템 생성) — 원시 파티션(Raw Partition)에 운영체제가 파일과 폴더를 기록하고 검색할 수 있도록 XFS(고성능 대용량 엔터프라이즈)나 ext4 규격으로 디스크를 포맷(초기화)\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"mount & /etc/fstab 영구 마운트 등록 (UUID 기반)\",\n        \"cmd\": \"UUID=$(blkid -s UUID -o value /dev/nvme0n2p1) && mkdir -p /data && echo \\\"UUID=$UUID /data xfs defaults 0 0\\\" >> /etc/fstab && mount -a\",\n        \"desc\": \"디스크 장치명이 바뀌어도 안전하도록 blkid 고유 UUID를 추출하여 /etc/fstab에 등록하고 mount -a로 즉시 무결성을 검증합니다.\",\n        \"scenario\": \"서버 재부팅 시에도 자동으로 마운트 지점이 복원되도록 보장하는 클라우드 인프라 표준 마운트 등록\",\n        \"tags\": [\n            \"mount\",\n            \"fstab\",\n            \"blkid\",\n            \"UUID\",\n            \"영구마운트\"\n        ],\n        \"abbr\": \"mount(저장소를 폴더에 결합) · fstab(File Systems Table: 부팅 마운트 설정 파일) · blkid(Block Device ID: 장치 고유 식별자) — 서버가 재부팅되어 디스크 장치명이 바뀌더라도 항상 올바른 폴더에 자동 연결되도록 UUID 기반 영구 등록\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"du 대용량 디렉토리 추적\",\n        \"cmd\": \"du -h --max-depth=1 /var | sort -hr | head -n 10\",\n        \"desc\": \"/var 디렉토리 직계 하위 폴더들의 실제 소비 용량을 계산하여 가장 용량을 많이 차지하는 상위 10개 폴더를 출력합니다.\",\n        \"scenario\": \"디스크 사용량 90% 이상 경보 시 어떤 애플리케이션 로그나 캐시가 급증했는지 주범 색출\",\n        \"tags\": [\n            \"du\",\n            \"디스크100%\",\n            \"용량추적\",\n            \"스토리지정리\"\n        ],\n        \"abbr\": \"du(Disk Usage: 디스크 사용량) — 디렉토리와 하위 파일들이 실제로 소비하고 있는 용량을 측정하여, 디스크가 꽉 찼을 때 어떤 로그 파일이나 폴더가 용량을 잡아먹고 있는지 주범 색출\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"LVM 3계층 물리 볼륨(PV) & 볼륨 그룹(VG) 생성\",\n        \"cmd\": \"pvcreate /dev/nvme0n2p1 /dev/nvme0n2p2 && vgcreate vg01 /dev/nvme0n2p1 /dev/nvme0n2p2 && vgs\",\n        \"desc\": \"여러 파티션을 LVM 물리 볼륨(PV)으로 변환한 후, 하나의 거대한 스토리지 풀인 볼륨 그룹(VG)으로 묶어 관리합니다.\",\n        \"scenario\": \"물리 디스크의 단일 파티션 크기 제약을 극복하고 유연하게 볼륨을 확장/축소하기 위한 LVM 스토리지 풀 기반 구성\",\n        \"tags\": [\n            \"LVM\",\n            \"pvcreate\",\n            \"vgcreate\",\n            \"스토리지풀\",\n            \"가상화\"\n        ],\n        \"abbr\": \"LVM(Logical Volume Manager: 논리 볼륨 관리자) — 물리 디스크(PV)의 경계를 허물고 하나의 거대한 가상 스토리지 풀(VG)로 묶어, 나중에 용량이 부족할 때 무중단으로 공간을 늘릴 수 있는 가상화 기반 스토리지 구축\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"LVM 논리 볼륨(LV) 생성 및 마운트\",\n        \"cmd\": \"lvcreate -L 1G -n lv_data vg01 && mkfs.xfs /dev/vg01/lv_data && mkdir -p /app_data && mount /dev/vg01/lv_data /app_data\",\n        \"desc\": \"볼륨 그룹(vg01)에서 원하는 크기(1GB)만큼 논리 볼륨(lv_data)을 잘라내어 XFS 포맷 후 마운트합니다.\",\n        \"scenario\": \"애플리케이션별 격리된 스토리지 볼륨을 생성하고 필요 시 동적으로 크기를 조정할 수 있도록 할당\",\n        \"tags\": [\n            \"LVM\",\n            \"lvcreate\",\n            \"논리볼륨\",\n            \"XFS\",\n            \"마운트\"\n        ],\n        \"abbr\": \"LV(Logical Volume: 논리 볼륨) — 볼륨 그룹(스토리지 풀)에서 필요한 용량(예: 1GB)만큼 가상 파티션을 자유롭게 잘라내어 포맷 후 마운트하는 동적 스토리지 할당\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"Swap 메모리 파티션 생성 & 동적 활성화\",\n        \"cmd\": \"mkswap /dev/nvme0n2p3 && swapon /dev/nvme0n2p3 && swapon --show\",\n        \"desc\": \"지정 파티션을 리눅스 스왑(가상 메모리) 영역으로 포맷하고 swapon으로 즉시 활성화하여 메모리 가용성을 높입니다.\",\n        \"scenario\": \"물리 RAM 부족으로 인한 OOM-Killer 프로세스 강제 종료를 사전에 방지하기 위한 가상 메모리 스왑 보강\",\n        \"tags\": [\n            \"Swap\",\n            \"스왑\",\n            \"가상메모리\",\n            \"swapon\",\n            \"OOM방지\"\n        ],\n        \"abbr\": \"swap(맞교환/가상 메모리) — 물리 RAM 메모리가 부족하여 프로그램이 강제 종료(OOM)되는 사태를 막기 위해, 디스크 파티션의 일부를 임시 보조 메모리 공간으로 전환하여 시스템 가용성 유지\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"df -i Inode 점검 (파일 개수 한도)\",\n        \"cmd\": \"df -ih\",\n        \"desc\": \"디스크 용량(Byte)이 남아있더라도 파일 개수 제한인 Inode 사용률이 100%에 도달했는지 확인합니다.\",\n        \"scenario\": \"'No space left on device' 에러가 뜨는데 df 용량은 넉넉할 때 세션/캐시 잔여 파일 고갈 진단\",\n        \"tags\": [\n            \"Inode\",\n            \"파일시스템\",\n            \"파일개수\",\n            \"트러블슈팅\"\n        ],\n        \"abbr\": \"inode(Index Node: 파일 인덱스 메타데이터 노드) — 디스크 용량(GB)이 많이 남아있더라도 파일 개수 한도(inode)가 100% 꽉 차면 신규 파일 생성이 불가능(No space left on device)하므로 잔여 파일 개수 한도를 점검\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"NFS 네트워크 공유 스토리지 서버 설정 & 마운트\",\n        \"cmd\": \"echo \\\"/share 192.168.0.0/24(rw,sync,no_root_squash)\\\" >> /etc/exports && exportfs -arv && showmount -e localhost\",\n        \"desc\": \"NFS 서버의 특정 디렉토리를 네트워크 서브넷에 읽기/쓰기(rw) 공유로 개방하고 클러스터 호스트들이 마운트할 수 있도록 내보냅니다.\",\n        \"scenario\": \"여러 대의 웹서버/WAS 서버가 동일한 파일(업로드 이미지, 소스코드)을 공유해야 하는 공용 NAS 스토리지 환경 구축\",\n        \"tags\": [\n            \"NFS\",\n            \"스토리지공유\",\n            \"exports\",\n            \"네트워크마운트\",\n            \"공유스토리지\"\n        ],\n        \"abbr\": \"NFS(Network File System: 네트워크 분산 파일시스템) — 여러 대의 웹 서버나 도커 노드가 중앙 스토리지 서버의 특정 폴더(/share)를 마치 자신의 로컬 하드디스크처럼 네트워크를 통해 공동으로 읽고 쓰도록 공유\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"LVM 무중단 온라인 볼륨 확장 (XFS / ext4)\",\n        \"cmd\": \"lvextend -L +2G /dev/vg01/lv_data && xfs_growfs /app_data\",\n        \"desc\": \"운영 중인 논리 볼륨(LV) 크기를 2GB 증설한 뒤, 언마운트 없이 xfs_growfs(ext4는 resize2fs)로 파일시스템 크기를 즉시 실시간 확장합니다.\",\n        \"scenario\": \"운영 서비스 중단 없이 데이터베이스나 로그 적재 볼륨의 용량을 실시간으로 안전하게 증설\",\n        \"tags\": [\n            \"LVM\",\n            \"lvextend\",\n            \"xfs_growfs\",\n            \"무중단확장\",\n            \"온라인증설\"\n        ],\n        \"abbr\": \"lvextend(Logical Volume Extend: 논리 볼륨 용량 확장) · xfs_growfs(XFS 파일시스템 온라인 증설) — 서비스를 중단하거나 마운트를 해제하지 않고, 운영 중인 상태 그대로 스토리지 공간을 실시간 증설\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"LVM 스냅샷 백업 생성 & 롤백 (Merge)\",\n        \"cmd\": \"lvcreate -s -L 500M -n snap_data /dev/vg01/lv_data && mount -o ro,nouuid /dev/vg01/snap_data /snap && lvconvert --merge /dev/vg01/snap_data\",\n        \"desc\": \"원본 볼륨의 특정 시점 변경점만 기록하는 COW(Copy-on-Write) 스냅샷을 생성하여 백업하고, 장애 시 과거 시점으로 원복합니다.\",\n        \"scenario\": \"대규모 소프트웨어 업데이트나 DB 스키마 마이그레이션 전 안전망 확보 및 장애 시 즉각 롤백\",\n        \"tags\": [\n            \"LVM\",\n            \"스냅샷\",\n            \"백업\",\n            \"롤백\",\n            \"COW\"\n        ],\n        \"abbr\": \"snapshot(순간 복제본) · merge(병합/원상 복구) — 대규모 시스템 업데이트나 위험한 작업 전 현재 디스크 상태를 사진 찍듯 순간 보관하고, 장애 발생 시 작업 전 상태로 즉시 롤백\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"mdadm 소프트웨어 RAID 1 (미러링) 구축\",\n        \"cmd\": \"mdadm --create /dev/md1 --level=1 --raid-devices=2 /dev/nvme0n2 /dev/nvme0n3 && cat /proc/mdstat\",\n        \"desc\": \"2개의 물리 디스크를 실시간 미러링(RAID 1) 배열로 묶어 커널 레벨에서 단일 디스크 고장 시 무중단 연속성을 제공합니다.\",\n        \"scenario\": \"고가의 하드웨어 RAID 컨트롤러 없이도 디스크 결함에 대비한 고가용성(HA) 데이터 스토리지 구성\",\n        \"tags\": [\n            \"RAID\",\n            \"mdadm\",\n            \"RAID1\",\n            \"미러링\",\n            \"고가용성\"\n        ],\n        \"abbr\": \"mdadm(Multiple Devices Administrator: 복수 장치 관리자) · RAID 1(미러링 이중화) — 두 개 이상의 디스크에 동일한 데이터를 실시간 동시 기록하여, 디스크 하나가 물리적으로 고장 나더라도 데이터 유실 없이 무중단 운영\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"RAID 디스크 고장 시뮬레이션 & 핫스왑 리빌딩\",\n        \"cmd\": \"mdadm --fail /dev/md1 /dev/nvme0n2 && mdadm --remove /dev/md1 /dev/nvme0n2 && mdadm --add /dev/md1 /dev/nvme0n4\",\n        \"desc\": \"불량 디스크를 결함 처리(--fail) 후 어레이에서 제거(--remove)하고, 신규 디스크를 투입(--add)하여 데이터 자동 동기화(Rebuild)를 수행합니다.\",\n        \"scenario\": \"디스크 물리적 베드섹터/장애 발생 시 서비스 중단 없이 안전한 예비 디스크 교체 및 데이터 무결성 복구\",\n        \"tags\": [\n            \"RAID\",\n            \"디스크복구\",\n            \"리빌딩\",\n            \"핫스왑\",\n            \"장애복구\"\n        ],\n        \"abbr\": \"--fail(결함 장치로 표기) · --remove(장애 디스크 제거) · --add(신규 디스크 교체 투입) — 실제 디스크 고장 상황을 가상으로 발생시키고, 새 디스크를 투입하여 백그라운드에서 데이터를 자동 복제 복구(Rebuilding)하는 실무 훈련\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"xfsdump / xfsrestore 증분 백업 및 복원\",\n        \"cmd\": \"xfsdump -l 0 -f /bk/xfs.dump0 /xfs && xfsrestore -rf /bk/xfs.dump0 /xfs_restore\",\n        \"desc\": \"XFS 파일시스템의 전체(Level 0) 또는 일자별 증분(Level 1~) 덤프를 생성하고 무결성 검증을 거쳐 지정 경로로 안전하게 복원합니다.\",\n        \"scenario\": \"대용량 XFS 파일시스템의 테이프/아카이브 스토리지 백업 및 재해 복구(DR) 자동화\",\n        \"tags\": [\n            \"xfsdump\",\n            \"xfsrestore\",\n            \"증분백업\",\n            \"재해복구\",\n            \"아카이빙\"\n        ],\n        \"abbr\": \"xfsdump(XFS 전용 덤프 백업) · xfsrestore(백업 복원) — XFS 파일시스템의 데이터와 메타데이터 구조를 있는 그대로 백업 파일로 추출하고, 변경된 데이터만 층층이 백업(증분 백업)하여 장애 시 완벽 복원\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"systemd journald 시스템 로그 디스크 영구 보존\",\n        \"cmd\": \"mkdir -p /var/log/journal && sed -i 's/^#Storage=.*/Storage=persistent/' /etc/systemd/journald.conf && systemctl restart systemd-journald\",\n        \"desc\": \"기본적으로 RAM(/run)에 휘발성으로 저장되는 바이너리 저널 로그를 디스크(/var/log/journal)에 영구 기록하도록 전환합니다.\",\n        \"scenario\": \"서버 커널 패닉이나 돌발 강제 재부팅 발생 후에도 크래시 직전의 시스템 로그와 오류 메시지 역추적 보장\",\n        \"tags\": [\n            \"journald\",\n            \"영구로깅\",\n            \"디스크로그\",\n            \"systemd\",\n            \"장애분석\"\n        ],\n        \"abbr\": \"journald(저널 로깅 데몬) — 기본적으로 RAM(/run)에 임시 저장되어 재부팅 시 사라지는 시스템 로그를 하드디스크(/var/log/journal)에 영구 보존하도록 설정하여 시스템 재부팅 후에도 장애 원인 추적 가능\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"iostat 실시간 디스크 I/O 병목 및 지연 측정\",\n        \"cmd\": \"iostat -xz 1 5\",\n        \"desc\": \"1초 간격으로 디스크 장치별 대기 시간(await)과 포화도(%util)를 측정하여 스토리지 하드웨어 병목을 포착합니다.\",\n        \"scenario\": \"애플리케이션이나 DB 쿼리 응답이 느릴 때 디스크 I/O 처리 한계(IOPS 초과)인지 확인\",\n        \"tags\": [\n            \"iostat\",\n            \"IOPS\",\n            \"병목진단\",\n            \"스토리지성능\"\n        ],\n        \"abbr\": \"iostat(Input/Output Statistics: 입출력 통계) — 디스크 장치가 초당 얼마나 많은 읽기/쓰기를 처리하고 있는지(r/s, w/s), 요청이 큐에서 얼마나 지연되고 있는지(await) 측정하여 스토리지 병목 원인 진단\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"삭제되었으나 프로세스가 쥐고 있는 유령 용량 해제\",\n        \"cmd\": \"lsof +L1 | grep deleted && truncate -s 0 /proc/{PID}/fd/{FD}\",\n        \"desc\": \"rm으로 파일을 지웠으나 실행 중인 데몬 프로세스가 FD를 열고 있어 디스크 용량이 반환되지 않을 때 파일 내용을 0바이트로 강제 비웁니다.\",\n        \"scenario\": \"운영 중인 Nginx/MySQL/Tomcat 프로세스를 재시작하지 않고도 디스크 Full 장애 즉시 긴급 해제\",\n        \"tags\": [\n            \"lsof\",\n            \"deleted\",\n            \"FD해제\",\n            \"긴급용량확보\",\n            \"무중단복구\"\n        ],\n        \"abbr\": \"lsof(List Open Files: 열린 파일 목록) · truncate(파일 크기 강제 절삭) — 파일을 rm 명령으로 지웠는데도 프로세스가 파일 디스크립터(fd)를 물고 있어서 디스크 용량이 반환되지 않을 때, 프로세스를 죽이지 않고 크기를 0으로 비워 용량 회수\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"cd / pwd / ls 현재 위치 및 숨김 파일 조회\",\n        \"cmd\": \"pwd && ls -la\",\n        \"desc\": \"현재 절대 경로를 확인하고 숨김 파일(.env, .git)을 포함한 상세 목록을 조회합니다.\",\n        \"scenario\": \"서버 접속 직후 현재 위치 확인 및 배포 디렉토리 파일 상태 점검\",\n        \"tags\": [\n            \"파일\",\n            \"기초\",\n            \"경로\",\n            \"ls\"\n        ],\n        \"abbr\": \"pwd(Print Working Directory: 현재 작업 경로) · ls(List: 목록 출력) · cd(Change Directory: 디렉토리 이동) — 리눅스 파일시스템 트리를 탐색하고 숨김 파일(-a)과 권한/크기 상세 정보(-l)를 확인하는 기본 명령어\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"mkdir -p / ln -s 심볼릭 링크 원자적 교체\",\n        \"cmd\": \"mkdir -p /app/releases/v1.0.0 && ln -sfn /app/releases/v1.0.0 /app/current\",\n        \"desc\": \"중간 경로를 안전하게 일괄 생성하고 무중단 배포를 위한 심볼릭 링크를 원자적으로 교체합니다.\",\n        \"scenario\": \"CI/CD 배포 스크립트에서 버전별 릴리즈 디렉토리 교체\",\n        \"tags\": [\n            \"배포\",\n            \"심링크\",\n            \"디렉토리\",\n            \"ln\"\n        ],\n        \"abbr\": \"mkdir -p(Make Directory Parents: 부모 경로까지 한 번에 생성) · ln -s(Link Symbolic: 바로가기 심볼릭 링크) — 소프트웨어 배포 시 새 버전 폴더를 만들고 심볼릭 링크를 순식간에 교체(원자적 배포)하여 무중단 롤아웃\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"find -mtime + exec 오래된 파일 자동 아카이빙\",\n        \"cmd\": \"find /var/log/app -type f -name \\\"*.log\\\" -mtime +30 -exec gzip {} \\\\;\",\n        \"desc\": \"30일 이상 수정되지 않은 로그 파일만 골라내어 일괄 gzip 압축합니다.\",\n        \"scenario\": \"디스크 용량 확보를 위한 정기 로그 로테이션 및 아카이빙 배치 작업\",\n        \"tags\": [\n            \"find\",\n            \"자동화\",\n            \"로그압축\",\n            \"아카이빙\"\n        ],\n        \"abbr\": \"find(파일 검색) · -mtime(Modification Time: 파일 수정 시간) · -exec(검색 결과에 명령 실행) — 30일 이상 지난 대용량 로그 파일들만 시스템에서 자동으로 찾아내어 압축 아카이브로 보관하거나 자동 정리\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"find + xargs 병렬 처리 (대량 파일 초고속 삭제)\",\n        \"cmd\": \"find /tmp/cache -type f -print0 | xargs -0 -P 4 -n 100 rm -f\",\n        \"desc\": \"수십만 개의 임시 파일을 공백 문자 깨짐 없이 4개 CPU 코어로 병렬 초고속 삭제합니다.\",\n        \"scenario\": \"Argument list too long 에러 해결 및 대규모 캐시 디렉토리 즉시 정리\",\n        \"tags\": [\n            \"xargs\",\n            \"병렬\",\n            \"성능\",\n            \"대량삭제\"\n        ],\n        \"abbr\": \"xargs(Extended Arguments: 표준 입력을 인자 배열로 변환) · -P(Parallel: CPU 병렬 실행) — 수십만 개의 임시 캐시 파일을 삭제할 때 인자 길이 초과(Argument list too long) 에러를 방지하고 CPU 멀티코어로 초고속 일괄 처리\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"rsync 증분 동기화 및 SSH 원격 미러링\",\n        \"cmd\": \"rsync -avzP --delete -e \\\"ssh -p 2222\\\" /src/ user@remote:/dst/\",\n        \"desc\": \"SSH 터널을 통해 변경된 차분 데이터만 압축 전송하며 이어받기 및 동일성 동기화를 보장합니다.\",\n        \"scenario\": \"서버 간 무중단 마이그레이션, 대용량 정적 자산 동기화\",\n        \"tags\": [\n            \"rsync\",\n            \"마이그레이션\",\n            \"네트워크동기화\",\n            \"백업\"\n        ],\n        \"abbr\": \"rsync(Remote Synchronization: 원격 증분 동기화) — 전체 파일을 매번 다시 복사하지 않고, 변경되거나 새로 추가된 파일 블록만 골라내어 SSH 암호화 통신으로 안전하고 신속하게 원격 백업 서버에 미러링 동기화\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"cat / head / tail 빠른 파일 검토\",\n        \"cmd\": \"head -n 20 /etc/nginx/nginx.conf\",\n        \"desc\": \"설정 파일의 최상단 20줄을 빠르게 검토합니다.\",\n        \"scenario\": \"설정 파일 구문 및 헤더 정보 단순 확인\",\n        \"tags\": [\n            \"텍스트\",\n            \"조회\",\n            \"head\",\n            \"tail\"\n        ],\n        \"abbr\": \"cat(Concatenate: 파일 내용 출력) · head(파일 첫 부분 출력) · tail(파일 끝부분 출력) — 무거운 편집기를 열지 않고도 설정 파일이나 로그의 앞/뒤 내용을 터미널에서 신속하게 검토\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"tail -f & grep 실시간 로그 에러 감시\",\n        \"cmd\": \"tail -f /var/log/app.log | grep --line-buffered -i \\\"exception\\\"\",\n        \"desc\": \"실시간으로 쌓이는 로그 스트림에서 대소문자 구분 없이 Exception 키워드를 즉시 포착합니다.\",\n        \"scenario\": \"신규 기능 배포 직후 실시간 에러 발생 모니터링\",\n        \"tags\": [\n            \"실시간로그\",\n            \"grep\",\n            \"모니터링\",\n            \"스트림\"\n        ],\n        \"abbr\": \"tail -f(Follow: 파일 끝 실시간 추적) · grep(Global Regular Expression Print: 정규식 검색) — 서버가 운영되는 동안 실시간으로 추가되는 애플리케이션 로그 스트림을 추적하며, ERROR나 EXCEPTION 같은 장애 키워드만 실시간 필터링\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"sed 설정 파일 비대화식 일괄 치환\",\n        \"cmd\": \"sed -i.bak 's/api.legacy.com/api.v2.com/g' /app/config/*.env\",\n        \"desc\": \"여러 설정 파일 내 도메인을 원본 백업(.bak)과 함께 비대화식으로 일괄 변경합니다.\",\n        \"scenario\": \"서버 환경 전환(Dev → Stage → Prod) 시 설정 파일 주입 자동화\",\n        \"tags\": [\n            \"sed\",\n            \"치환\",\n            \"자동화\",\n            \"설정변경\"\n        ],\n        \"abbr\": \"sed(Stream Editor: 스트림 기반 텍스트 편집기) · -i(In-place: 원본 직접 수정) — 사람이 vi로 파일을 열어 일일이 수정하지 않고, 명령줄 스크립트를 통해 설정 파일 안의 구버전 도메인이나 IP 주소를 신규 주소로 일괄 자동 치환\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"awk 컬럼 필터 & 상태코드 집계\",\n        \"cmd\": \"awk '$9 >= 500 {print $1, $7, $9}' access.log | sort | uniq -c | sort -nr | head -10\",\n        \"desc\": \"500번대 서버 에러를 유발한 클라이언트 IP와 요청 URL 상위 10개를 집계합니다.\",\n        \"scenario\": \"장애 발생 시 병목 엔드포인트 및 공격자 IP 역추적\",\n        \"tags\": [\n            \"awk\",\n            \"로그분석\",\n            \"통계\",\n            \"장애추적\"\n        ],\n        \"abbr\": \"awk(텍스트 패턴 검색 및 데이터 가공 언어) — 엑셀처럼 띄어쓰기 기준으로 9번째 열(HTTP 상태코드), 7번째 열(URL) 등 특정 필드만 뽑아내어 장애 상태코드(500) 빈도를 실시간으로 집계 및 정렬\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"jq 구조화 JSON 로그 파싱 & 추출\",\n        \"cmd\": \"tail -n 5000 log.json | jq -r 'select(.level==\\\"ERROR\\\") | [.timestamp, .userId, .errorMsg] | @tsv'\",\n        \"desc\": \"JSON 구조화 로그에서 ERROR 레벨만 추출하여 TSV(Tab-Separated) 형태로 재가공합니다.\",\n        \"scenario\": \"클라우드 네이티브 JSON 로그 파이프라인에서 즉시 장애 데이터 추출\",\n        \"tags\": [\n            \"jq\",\n            \"JSON\",\n            \"구조화데이터\",\n            \"파싱\"\n        ],\n        \"abbr\": \"jq(JSON Query: 커맨드라인 JSON 프로세서) — 복잡한 중첩 JSON 형식의 최신 애플리케이션 로그나 REST API 응답 결과에서 에러 메시지와 타임스탬프 등 필요한 키(Key) 값만 깔끔하게 파싱하여 추출\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"ps / top 실시간 시스템 부하 점검\",\n        \"cmd\": \"top -b -n 1 | head -n 20\",\n        \"desc\": \"실시간 시스템 CPU/메모리 점유율과 프로세스 목록을 확인합니다.\",\n        \"scenario\": \"서버 리소스 사용량 및 시스템 로드 에버리지(Load Average) 1차 점검\",\n        \"tags\": [\n            \"CPU\",\n            \"top\",\n            \"프로세스\",\n            \"부하\"\n        ],\n        \"abbr\": \"ps(Process Status: 프로세스 상태) · top(Table of Processes: 실시간 작업 관리자) — 현재 CPU나 메모리를 과도하게 점유하여 시스템을 느리게 만드는 이상 프로세스를 실시간으로 모니터링하고 원인 파악\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"ps -ef & kill 우아한 프로세스 종료 (SIGTERM)\",\n        \"cmd\": \"ps -ef | grep java | grep -v grep | awk '{print $2}' | xargs kill -15\",\n        \"desc\": \"실행 중인 Java 프로세스의 PID를 찾아 우아하게(Graceful, SIGTERM 15) 종료합니다.\",\n        \"scenario\": \"애플리케이션 재시작 및 좀비 프로세스 정리\",\n        \"tags\": [\n            \"kill\",\n            \"시그널\",\n            \"프로세스\",\n            \"PID\"\n        ],\n        \"abbr\": \"kill(시그널 전송) · SIGTERM(Signal Terminate: 정상 종료 요청, 15번) · SIGKILL(강제 종료, 9번) — 프로세스가 처리 중이던 데이터를 안전하게 저장하고 락을 풀며 종료하도록 신사적인 종료(15번)를 먼저 시도\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"ps CPU/메모리 최상위 프로세스 정렬\",\n        \"cmd\": \"ps -eo pid,ppid,user,%cpu,%mem,cmd --sort=-%cpu | head -n 11\",\n        \"desc\": \"CPU를 가장 많이 소비하는 최상위 10개 프로세스를 리소스 상세 정보와 함께 출력합니다.\",\n        \"scenario\": \"CPU 100% 급증 시 즉각적인 원인 프로세스 색출\",\n        \"tags\": [\n            \"CPU스파이크\",\n            \"리소스추적\",\n            \"ps정렬\"\n        ],\n        \"abbr\": \"ps -eo(출력 컬럼 지정) · --sort(정렬 기준) — 프로세스 ID(PID), 사용자, CPU 사용률, 메모리 사용률을 표 형태로 구성하고, 자원을 가장 많이 쓰는 순서대로 내림차순 정렬하여 병목 프로세스 즉시 확인\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"lsof 열린 파일 디스크립터 및 활성 소켓 추적\",\n        \"cmd\": \"lsof -p $(pgrep -f \\\"node server.js\\\") | grep -E \\\"(LISTEN|ESTABLISHED)\\\"\",\n        \"desc\": \"특정 Node.js 애플리케이션이 열고 있는 파일 디스크립터 및 활성 소켓을 추적합니다.\",\n        \"scenario\": \"File Descriptor 누수(Too many open files) 및 소켓 누수 진단\",\n        \"tags\": [\n            \"lsof\",\n            \"FD\",\n            \"소켓\",\n            \"누수진단\"\n        ],\n        \"abbr\": \"lsof(List Open Files: 열려있는 파일 및 소켓 목록) — 특정 프로세스가 현재 디스크의 어떤 파일, 설정, 네트워크 소켓 포트를 붙잡고 열어두었는지 실시간으로 추적하여 리소스 누수(Leak) 점검\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"strace 시스템 콜 지연시간 프로파일링\",\n        \"cmd\": \"strace -p 12345 -c -S time\",\n        \"desc\": \"프로세스가 호출하는 커널 시스템 콜(read, epoll, futex 등)의 지연시간을 요약 프로파일링합니다.\",\n        \"scenario\": \"애플리케이션이 멈추거나(Hang) 응답이 없을 때 블로킹 원인 규명\",\n        \"tags\": [\n            \"strace\",\n            \"시스템콜\",\n            \"디버깅\",\n            \"블로킹\"\n        ],\n        \"abbr\": \"strace(System Call Trace: 커널 시스템 콜 추적) — 프로그램이 커널에 요청하는 시스템 호출(파일 읽기, 네트워크 통신 등)의 시간 지연을 밀리초 단위로 프로파일링하여 코드가 어디서 멈춰있는지 디버깅\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"ip addr / ip link 인터페이스 상태 점검\",\n        \"cmd\": \"ip addr show eth0\",\n        \"desc\": \"네트워크 인터페이스 IP 주소 및 상태(UP/DOWN)를 확인합니다.\",\n        \"scenario\": \"서버 IP 할당 및 네트워크 연결 기본 확인\",\n        \"tags\": [\n            \"IP\",\n            \"기초네트워크\",\n            \"ipaddr\"\n        ],\n        \"abbr\": \"ip addr(IP 주소 관리) · ip link(데이터 링크 계층 인터페이스 관리) — 구식 ifconfig를 대체하는 표준 명령어로, 네트워크 카드의 MAC 주소, 링크 연결 상태, 할당된 IP 주소 대역을 확인\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"curl HTTP 구간별 응답 지연시간(TTFB) 정밀 측정\",\n        \"cmd\": \"curl -ivk -w \\\"DNS: %{time_namelookup}s | Connect: %{time_connect}s | TTFB: %{time_starttransfer}s | Total: %{time_total}s\\\\n\\\" https://api.service.internal/health\",\n        \"desc\": \"HTTP 요청 시 DNS 조회, TCP 핸드셰이크, 첫 바이트 응답(TTFB)까지의 지연시간을 밀리초 단위로 분해 측정합니다.\",\n        \"scenario\": \"API 응답 지연 구간(네트워크 vs 앱 로직) 정밀 판별\",\n        \"tags\": [\n            \"curl\",\n            \"TTFB\",\n            \"API지연\",\n            \"성능측정\"\n        ],\n        \"abbr\": \"curl(Client URL 전송기) · TTFB(Time To First Byte: 첫 바이트 수신 시간) — 웹 요청 시 DNS 해석 시간, TCP 핸드셰이크 시간, TLS 암호화 시간, 서버가 첫 응답을 보낸 시간을 각각 분리 측정하여 웹 성능 병목 진단\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"nc (netcat) 포트 스캔 및 방화벽 개방 점검\",\n        \"cmd\": \"nc -zvw 3 db-cluster.internal 3306\",\n        \"desc\": \"원격 DB 서버의 3306 포트로 TCP 핸드셰이크를 3초 타임아웃으로 시도하여 방화벽 오픈을 점검합니다.\",\n        \"scenario\": \"마이크로서비스 간 VPC 방화벽 및 Security Group 통신 개방 확인\",\n        \"tags\": [\n            \"nc\",\n            \"방화벽\",\n            \"포트점검\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"nc(Netcat: 네트워크 만능 잭) · -z(Zero-I/O: 데이터 전송 없이 연결만 확인) · -v(Verbose: 상세 출력) — 목적지 서버의 데이터베이스(3306)나 웹 포트가 실제로 열려있는지, 중간 방화벽이 차단하고 있는지 즉시 테스트\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"ss 초고속 TCP 연결 상태 분포 분석\",\n        \"cmd\": \"ss -tan | awk '{print $1}' | sort | uniq -c\",\n        \"desc\": \"현재 시스템의 TCP 상태(TIME_WAIT, CLOSE_WAIT, ESTABLISHED) 분포를 고속 집계합니다.\",\n        \"scenario\": \"HTTP 커넥션 풀 고갈 및 TIME_WAIT 소켓 폭증 감지\",\n        \"tags\": [\n            \"ss\",\n            \"TIME_WAIT\",\n            \"소켓분석\",\n            \"TCP\"\n        ],\n        \"abbr\": \"ss(Socket Statistics: 소켓 통계 분석기) — 구식 netstat 대비 100배 빠르게 커널에서 소켓 다이어그램을 직접 조회하여, 동시 접속자 수와 ESTABLISHED, TIME-WAIT, CLOSE-WAIT 등 TCP 연결 상태를 초고속 집계\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"tcpdump L7 HTTP 패킷 페이로드 캡처\",\n        \"cmd\": \"tcpdump -i any -nn -s0 -A 'tcp port 80 and (((ip[2:2] - ((ip[0]&0xf)<<2)) - ((tcp[12:2]&0xf0)>>2)) != 0)' -c 5\",\n        \"desc\": \"80 포트의 HTTP 페이로드(본문) 패킷만 필터링하여 아스키 형태로 캡처합니다.\",\n        \"scenario\": \"L7 게이트웨이와 백엔드 간 헤더 유실 또는 비정상 패킷 실시간 분석\",\n        \"tags\": [\n            \"tcpdump\",\n            \"패킷캡처\",\n            \"L7분석\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"tcpdump(TCP 패킷 덤프 분석기) · -A(ASCII 텍스트로 출력) — 네트워크 카드를 통과하는 실제 네트워크 패킷을 가로채서, 평문 HTTP 요청 헤더와 응답 데이터를 있는 그대로 화면에 캡처하여 프로토콜 트러블슈팅\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"chmod +x / sudo 스크립트 실행 권한 부여\",\n        \"cmd\": \"chmod +x deploy.sh && sudo ./deploy.sh\",\n        \"desc\": \"스크립트에 실행 권한을 부여하고 관리자 권한으로 실행합니다.\",\n        \"scenario\": \"새로 작성한 배포 스크립트 실행\",\n        \"tags\": [\n            \"권한\",\n            \"chmod\",\n            \"sudo\",\n            \"보안\"\n        ],\n        \"abbr\": \"chmod(Change Mode: 파일 권한 모드 변경) · sudo(Superuser Do: 최고 관리자 권한으로 실행) — 일반 텍스트 스크립트 파일에 실행 권한(+x)을 부여하여 프로그램처럼 직접 구동할 수 있도록 권한을 변경\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"chown 소유권 이전 및 표준 웹 디렉토리 권한\",\n        \"cmd\": \"chown -R www-data:www-data /var/www/html && chmod 755 /var/www/html\",\n        \"desc\": \"웹서버 데몬 계정에 소유권을 이전하고 안전한 표준 디렉토리 권한을 적용합니다.\",\n        \"scenario\": \"웹서버 파일 업로드 권한 오류(403 Forbidden) 해결\",\n        \"tags\": [\n            \"chown\",\n            \"보안\",\n            \"소유권\",\n            \"403에러\"\n        ],\n        \"abbr\": \"chown(Change Owner: 소유자 및 소유그룹 변경) — 파일이나 디렉토리의 주인 계정을 웹서버 계정(www-data, nginx)으로 넘겨주어, 웹 애플리케이션이 파일 업로드나 읽기 작업을 권한 거부(Permission Denied) 없이 수행하도록 조치\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"SSH 무차별 대입 공격 IP 색출 및 차단 목록화\",\n        \"cmd\": \"grep \\\"Failed password\\\" /var/log/auth.log | awk '{print $(NF-3)}' | sort | uniq -c | sort -nr | head -10\",\n        \"desc\": \"인증 실패 로그에서 비정상적인 SSH 로그인 시도 공격자 IP 상위 10개를 추출합니다.\",\n        \"scenario\": \"보안 침해 시도 모니터링 및 방화벽 차단 IP 목록 확보\",\n        \"tags\": [\n            \"보안\",\n            \"auth.log\",\n            \"공격자추적\",\n            \"SSH\"\n        ],\n        \"abbr\": \"grep(문자열 검색) · sort & uniq -c(중복 카운트 및 정렬) — 보안 인증 로그(/var/log/auth.log)에서 비밀번호 입력 실패(Failed password)를 유발한 해킹 시도 IP를 추출하고 빈도를 집계하여 방화벽 차단 목록 생성\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"setfacl 세부 접근제어 목록 (ACL) 상속\",\n        \"cmd\": \"setfacl -R -m u:deployer:rwx,d:u:deployer:rwx /var/www/shared\",\n        \"desc\": \"기본 소유 그룹을 변경하지 않고 특정 배포자 계정에만 디렉토리 및 향후 생성될 파일에 전체 권한을 상속합니다.\",\n        \"scenario\": \"멀티 유저/CI 환경에서 안전한 디렉토리 공유 권한 부여\",\n        \"tags\": [\n            \"ACL\",\n            \"setfacl\",\n            \"권한상속\",\n            \"보안\"\n        ],\n        \"abbr\": \"setfacl(Set File Access Control Lists: 세부 접근제어 목록 설정) — 전통적인 기본 권한(소유자-그룹-기타)의 한계를 넘어, 특정 사용자나 배포 계정(deployer)에게만 읽기/쓰기 권한을 별도로 부여하고 신규 생성 파일에도 권한 자동 상속\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"chattr +i 커널 불변(Immutable) 속성 락\",\n        \"cmd\": \"chattr +i /etc/resolv.conf && lsattr /etc/resolv.conf\",\n        \"desc\": \"root 사용자라도 파일 내용을 변경하거나 삭제할 수 없도록 커널 레벨의 불변(Immutable) 락을 겁니다.\",\n        \"scenario\": \"DHCP나 악성 프로세스에 의한 DNS 설정 및 중요 시스템 파일 임의 변조 방지\",\n        \"tags\": [\n            \"chattr\",\n            \"불변속성\",\n            \"커널보안\",\n            \"락\"\n        ],\n        \"abbr\": \"chattr(Change Attribute: 파일 고유 속성 변경) · +i(Immutable: 불변 속성) — root 최고 관리자라 할지라도 파일을 수정하거나 삭제, 이름 변경할 수 없도록 커널 레벨에서 잠가, DNS 설정(/etc/resolv.conf)이나 보안 파일 위변조 방지\"\n    },\n    {\n        \"cat\": \"sre\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"vmstat 시스템 런큐 및 컨텍스트 스위칭 진단\",\n        \"cmd\": \"vmstat -w 1 10\",\n        \"desc\": \"CPU 런큐(r), 블로킹 프로세스(b), 메모리 스왑(si/so), 컨텍스트 스위칭(cs) 빈도를 초단위 모니터링합니다.\",\n        \"scenario\": \"CPU 사용률은 낮은데 서버 응답이 느릴 때 Context Switch 과다 여부 판별\",\n        \"tags\": [\n            \"vmstat\",\n            \"ContextSwitch\",\n            \"부하진단\",\n            \"SRE\"\n        ],\n        \"abbr\": \"vmstat(Virtual Memory Statistics: 가상 메모리 및 CPU 프로세스 통계) — CPU 실행을 기다리는 런큐(r), I/O 대기(b), 초당 컨텍스트 스위칭 횟수(cs)를 종합 출력하여 시스템이 왜 버벅거리는지 근본 체력 진단\"\n    },\n    {\n        \"cat\": \"sre\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"bpftrace eBPF 커널 레벨 TCP 연결 실시간 추적\",\n        \"cmd\": \"bpftrace -e 'kprobe:tcp_connect { printf(\\\"TCP Connect from PID %d (%s)\\\\n\\\", pid, comm); }'\",\n        \"desc\": \"커널 소스 수정이나 오버헤드 없이 실시간 TCP 연결을 시도하는 프로세스를 eBPF로 캡처합니다.\",\n        \"scenario\": \"의심스러운 외부 통신을 수행하는 백도어나 간헐적 네트워크 지연 추적\",\n        \"tags\": [\n            \"eBPF\",\n            \"bpftrace\",\n            \"커널추적\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"bpftrace(eBPF 기반 프로그래머블 커널 트레이서) — 커널 소스코드를 고치거나 서버를 재부팅하지 않고도, 커널 내부 TCP 연결 함수(tcp_connect)에 미세 탐침을 꽂아 실시간으로 어떤 프로세스가 어디로 통신을 시도하는지 0.01% 미만 오버헤드로 추적\"\n    },\n    {\n        \"cat\": \"sre\",\n        \"lvl\": \"L5\",\n        \"lvlName\": \"심화 L5\",\n        \"name\": \"sysctl 대규모 트래픽 대비 TCP 커널 파라미터 튜닝\",\n        \"cmd\": \"sysctl -w net.core.somaxconn=65535 && sysctl -w net.ipv4.tcp_max_syn_backlog=65535\",\n        \"desc\": \"대규모 트래픽 처리를 위해 TCP 수신 대기 큐 및 SYN 백로그 크기를 즉시 튜닝합니다.\",\n        \"scenario\": \"대규모 프로모션/이벤트 시 SYN Flooding 방지 및 연결 유실 방지\",\n        \"tags\": [\n            \"sysctl\",\n            \"커널튜닝\",\n            \"고부하대응\",\n            \"성능최적화\"\n        ],\n        \"abbr\": \"sysctl(System Control: 커널 런타임 매개변수 제어) — 대규모 동시 접속 트래픽 환경에서 TCP 연결 수락 대기 큐(somaxconn)와 포트 고갈을 방지하도록 리눅스 커널 네트워크 스택 설정을 재부팅 없이 즉시 튜닝\"\n    },\n    {\n        \"cat\": \"scenario\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"시나리오: 백엔드\",\n        \"name\": \"API 응답 지연 종합 진단 파이프라인\",\n        \"cmd\": \"journalctl -u backend-api --since \\\"10 min ago\\\" | grep -A 5 \\\"NullPointerException\\\" | head -n 30\",\n        \"desc\": \"최근 10분간 발생한 애플리케이션 치명적 에러 스택트레이스를 즉시 추출합니다.\",\n        \"scenario\": \"배포 후 알람 발생 시 신속한 롤백/핫픽스 결정 근거 확보\",\n        \"tags\": [\n            \"백엔드\",\n            \"스택트레이스\",\n            \"장애대응\",\n            \"journalctl\"\n        ],\n        \"abbr\": \"journalctl & tail & awk 파이프라인 — 애플리케이션의 최근 저널 로그를 추적하여 응답 시간이 1초(1000ms)를 초과한 느린 API 엔드포인트 URL만 필터링하여 개발팀에 성능 개선 포인트 전달\"\n    },\n    {\n        \"cat\": \"scenario\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"시나리오: DevOps\",\n        \"name\": \"Docker 미사용 빌드 캐시 및 오래된 볼륨 일괄 정리\",\n        \"cmd\": \"docker system df && docker system prune -af --volumes --filter \\\"until=168h\\\"\",\n        \"desc\": \"도커 컨테이너 빌드 캐시 및 7일(168시간) 이상 미사용된 볼륨/이미지를 안전하게 일괄 삭제합니다.\",\n        \"scenario\": \"CI/CD 빌드 러너 머신의 Disk Full 장애 방지 자동화\",\n        \"tags\": [\n            \"Docker\",\n            \"DevOps\",\n            \"CI/CD\",\n            \"용량관리\"\n        ],\n        \"abbr\": \"prune(불필요한 리소스 가지치기 정리) — 7일 이상 쓰이지 않고 버려진 도커 빌드 캐시와 이름 없는 찌꺼기 볼륨들을 일괄 정리하여 수십 GB의 호스트 디스크 용량을 신속 복구\"\n    },\n    {\n        \"cat\": \"scenario\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"시나리오: SRE\",\n        \"name\": \"OOM (Out Of Memory) 킬러 프로세스 추적\",\n        \"cmd\": \"dmesg -T | grep -i -E \\\"(killed process|oom_reaper|out of memory)\\\" | tail -n 20\",\n        \"desc\": \"리눅스 커널이 메모리 부족으로 강제 종료(OOM-Kill)시킨 프로세스 명단과 시점을 타임스탬프로 확인합니다.\",\n        \"scenario\": \"프로세스가 로그도 남기지 못하고 갑자기 죽었을 때 원인 규명\",\n        \"tags\": [\n            \"OOM\",\n            \"dmesg\",\n            \"메모리릭\",\n            \"커널\"\n        ],\n        \"abbr\": \"dmesg(커널 메시지 버퍼 출력) · OOM(Out Of Memory: 메모리 고갈 킬러) — 물리 메모리가 한계에 도달했을 때 리눅스 커널이 시스템 전체 다운을 막기 위해 어떤 프로세스(Java, Node 등)를 강제로 사살했는지 원인 규명\"\n    },\n    {\n        \"cat\": \"scenario\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"시나리오: 인프라/스토리지\",\n        \"name\": \"디스크 100% 긴급 대응 LVM 온라인 무중단 증설 파이프라인\",\n        \"cmd\": \"df -h /data && vgs vg01 && lvextend -L +10G /dev/vg01/lv_data && xfs_growfs /data && df -h /data\",\n        \"desc\": \"운영 중인 서비스의 디스크 풀(Disk Full) 임계치 도달 시, 볼륨 그룹 여유 공간을 확인하고 논리 볼륨과 XFS 파일시스템을 무중단 온라인 확장합니다.\",\n        \"scenario\": \"데이터베이스/로그 파티션 급증으로 인한 서비스 다운타임을 제로(0초)로 방어하는 긴급 운영 조치\",\n        \"tags\": [\n            \"LVM\",\n            \"디스크100%\",\n            \"무중단확장\",\n            \"긴급대응\",\n            \"XFS\"\n        ],\n        \"abbr\": \"vgs(볼륨그룹 잔여용량 확인) & lvextend(논리볼륨 확장) & xfs_growfs(파일시스템 확장) — 데이터 디스크가 100% 가득 차서 서비스가 멈추기 직전, 무중단으로 스토리지 용량을 10GB 추가하고 파일시스템에 즉시 반영\"\n    },\n    {\n        \"cat\": \"scenario\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"시나리오: 컨테이너 장애\",\n        \"name\": \"도커 컨테이너 비정상 종료(Exit Code) 역추적 파이프라인\",\n        \"cmd\": \"docker ps -a --filter \\\"status=exited\\\" --format \\\"table {{.Names}}\\\\t{{.Status}}\\\\t{{.Image}}\\\" && docker logs --tail 50 web-app && docker inspect --format='{{.State.ExitCode}}' web-app\",\n        \"desc\": \"비정상 종료된 컨테이너들을 일괄 필터링하고 마지막 50줄의 표준 에러 로그와 프로세스 Exit Code를 즉시 추출합니다.\",\n        \"scenario\": \"CrashLoopBackOff 상태에 빠진 웹/API 컨테이너의 근본 원인(설정 오류, 포그라운드 누락, 포트 충돌) 즉각 진단\",\n        \"tags\": [\n            \"Docker\",\n            \"CrashLoop\",\n            \"ExitCode\",\n            \"컨테이너장애\",\n            \"로그추적\"\n        ],\n        \"abbr\": \"docker ps -a & inspect & logs — 갑자기 꺼져버린(Exited) 컨테이너의 종료 코드(Exit Code 137은 OOM 메모리 부족, 1은 애플리케이션 에러 등)와 마지막 표준 에러 로그를 역추적하여 장애 원인 분석\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"firewall-cmd 영구 포트/서비스 개방 & 즉시 반영\",\n        \"cmd\": \"sudo firewall-cmd --permanent --add-service=nfs --add-port=8080/tcp && sudo firewall-cmd --reload && sudo firewall-cmd --list-all\",\n        \"desc\": \"Rocky Linux firewalld 동적 방화벽에 지정 서비스 및 포트를 영구(--permanent) 등록하고 즉시 재적용하여 활성 규칙을 일람합니다.\",\n        \"abbr\": \"firewall-cmd(Firewall Daemon Command: RHEL/Rocky 방화벽 제어기) — 외부에서 서버로 들어오는 접속 요청을 통제하며, 웹(8080)이나 NFS(2049) 같은 신규 서비스를 재부팅 후에도 유지되도록 영구(--permanent) 허용 등록하고 즉시 활성화\",\n        \"scenario\": \"웹 서버(80/8080), NFS 스토리지(2049) 등 신규 서비스 설치 후 외부 클라이언트 접속 차단 해제\",\n        \"tags\": [\n            \"Rocky\",\n            \"firewalld\",\n            \"방화벽\",\n            \"포트개방\",\n            \"보안\"\n        ]\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"SELinux 웹 디렉토리 보안 컨텍스트 등록 & 복원\",\n        \"cmd\": \"sudo semanage fcontext -a -t httpd_sys_content_t '/www(/.*)?' && sudo restorecon -RFv /www && ls -lZ /www\",\n        \"desc\": \"기본 경로(/var/www/html)가 아닌 커스텀 경로(/www) 생성 시 SELinux가 파일 접근을 차단(403 Forbidden)하는 문제를 해결하기 위해 아파치 시스템 컨텍스트를 할당하고 복원합니다.\",\n        \"abbr\": \"semanage(SELinux Policy Manager: 보안 정책 관리자) · restorecon(Restore Context: 보안 레이블 복원) — Rocky Linux에서 기본 경로(/var/www/html)가 아닌 임의의 폴더(/www)를 웹 루트로 사용할 때 발생하는 403 Forbidden 에러를 해결하기 위해 올바른 아파치 접근 권한 레이블을 할당\",\n        \"scenario\": \"Rocky Linux에서 Nginx/Apache DocumentRoot 변경 후 403 Forbidden 권한 에러 긴급 조치\",\n        \"tags\": [\n            \"Rocky\",\n            \"SELinux\",\n            \"semanage\",\n            \"restorecon\",\n            \"보안컨텍스트\"\n        ]\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"SELinux 비표준 서비스 포트 바인딩 허용\",\n        \"cmd\": \"sudo semanage port -a -t http_port_t -p tcp 82 && sudo semanage port -l -C | grep http_port_t\",\n        \"desc\": \"Rocky Linux에서 Nginx나 Apache를 80/443이 아닌 비표준 포트(82번 등)로 바인딩할 때 SELinux Permission Denied 에러를 해결하도록 포트 정책을 추가합니다.\",\n        \"abbr\": \"semanage port(SELinux 포트 정책 관리) — Rocky Linux에서 웹서버를 표준 80번이 아닌 82번 같은 비표준 포트로 변경했을 때, 커널 보안 모듈이 포트 바인딩을 차단(Permission Denied)하지 못하도록 허용 포트 목록에 등록\",\n        \"scenario\": \"웹 서버 포트를 82, 8080 등으로 변경 시 systemd 기동 실패(Permission Denied) 해소\",\n        \"tags\": [\n            \"Rocky\",\n            \"SELinux\",\n            \"포트허용\",\n            \"네트워크보안\",\n            \"semanage\"\n        ]\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"nmcli 네트워크 연결 수정 & 보조 IP 동적 추가\",\n        \"cmd\": \"nmcli con mod mynet +ipv4.addresses 10.0.0.10/24 && nmcli con up mynet && ip -br addr\",\n        \"desc\": \"Rocky Linux 표준 NetworkManager CLI로 기존 네트워크 인터페이스 연결 프로필에 서브넷 보조 IP를 추가하고 즉시 활성화합니다.\",\n        \"abbr\": \"nmcli(NetworkManager CLI: 네트워크 관리자 명령어) — Rocky Linux 표준 네트워크 설정 도구로, 기존 네트워크 카드 연결 프로필에 보조 IP(Secondary IP)를 추가하여 하나의 랜선으로 두 개의 IP 대역을 동시 수신\",\n        \"scenario\": \"단일 NIC 이더넷 장치에 공인 IP와 사설 스토리지/내부 통신용 보조 IP를 멀티 바인딩\",\n        \"tags\": [\n            \"Rocky\",\n            \"nmcli\",\n            \"NetworkManager\",\n            \"IP할당\",\n            \"네트워크\"\n        ]\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"fuser 마운트 지점 점유 프로세스 강제 종료 & 언마운트\",\n        \"cmd\": \"fuser -km /m1 && sleep 1 && umount /m1\",\n        \"desc\": \"디스크 마운트 해제 시 'target is busy' 에러를 유발하는, 해당 마운트 지점에 위치하거나 파일을 열고 있는 모든 프로세스를 일괄 강제 종료(-k)하고 안전하게 언마운트합니다.\",\n        \"abbr\": \"fuser(File User: 파일/마운트 지점 점유 프로세스 식별기) — 디스크를 언마운트(umount)하려 할 때 'target is busy' 에러를 내며 디스크 분리를 방해하는 사용자 셸이나 백그라운드 프로세스를 찾아내어 일괄 강제 종료(-k)\",\n        \"scenario\": \"스토리지 디스크 분리, 파일시스템 포맷 변경 전 unmount 거부(Device or resource busy) 즉시 해결\",\n        \"tags\": [\n            \"Rocky\",\n            \"fuser\",\n            \"umount\",\n            \"busy해제\",\n            \"디스크관리\"\n        ]\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"스왑 파일(Swapfile) 생성 & 안전 권한 활성화\",\n        \"cmd\": \"dd if=/dev/zero of=/var/tmp/swapfile bs=1M count=1024 && chmod 600 /var/tmp/swapfile && mkswap /var/tmp/swapfile && swapon /var/tmp/swapfile && swapon --show\",\n        \"desc\": \"별도의 물리 디스크 파티션 분할 없이 dd로 지정 용량(1GB)의 빈 파일을 생성하고 보안 권한(600)을 부여한 뒤 가상 메모리 스왑 공간으로 즉시 활성화합니다.\",\n        \"abbr\": \"dd(Data Duplicator: 빈 블록 파일 생성) · mkswap(스왑 영역 포맷) · swapon(스왑 메모리 활성화) — 남는 하드디스크 파티션이 없을 때, 일반 파일 하나를 만들어 권한(600)을 잠근 뒤 물리 RAM을 보조하는 가상 메모리 스왑 공간으로 즉시 투입\",\n        \"scenario\": \"물리 파티션을 나눌 여유 공간이 없는 클라우드 인스턴스에서 메모리 고갈(OOM) 방지 긴급 스왑 확장\",\n        \"tags\": [\n            \"Rocky\",\n            \"swapfile\",\n            \"mkswap\",\n            \"swapon\",\n            \"가상메모리\"\n        ]\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"systemctl 서비스 즉시 기동 & 부팅 자동 실행 일괄 등록\",\n        \"cmd\": \"sudo systemctl daemon-reload && sudo systemctl enable --now docker httpd && sudo systemctl is-active docker\",\n        \"desc\": \"systemd 유닛 설정 파일 변경 사항을 커널 데몬에 재적용(daemon-reload)하고, 서비스를 즉시 시작함과 동시에 서버 부팅 시 자동 기동(--now)되도록 한 번에 등록합니다.\",\n        \"abbr\": \"systemctl(Systemd Control: 시스템 및 서비스 관리 제어기) · --now(Enable과 Start 동시 실행) — 서비스를 지금 당장 시작하는 것과 서버가 재부팅될 때 자동으로 켜지도록 등록하는 두 가지 작업을 한 번에 처리\",\n        \"scenario\": \"Rocky Linux에서 서비스 설치 후 수동 start 및 enable 2단계를 단일 명령으로 신속 표준화\",\n        \"tags\": [\n            \"Rocky\",\n            \"systemctl\",\n            \"systemd\",\n            \"서비스관리\",\n            \"daemon-reload\"\n        ]\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"dnf 리포지토리 패키지 설치 & rpm 역추적 쿼리\",\n        \"cmd\": \"sudo dnf install -y epel-release htop && rpm -qa | grep -i docker && rpm -ql htop | head -n 15\",\n        \"desc\": \"Rocky Linux 패키지 관리자 dnf로 EPEL 확장 저장소 및 도구를 자동 설치하고, rpm 데이터베이스에서 설치된 패키지 목록(-qa) 및 구성 파일 경로(-ql)를 역추적합니다.\",\n        \"abbr\": \"dnf(Dandified YUM: Rocky 리눅스 최신 패키지 관리자) · rpm(Red Hat Package Manager) — 인터넷 저장소에서 필요한 프로그램을 자동 설치하고, 내 컴퓨터에 설치된 특정 명령어 파일이 어떤 패키지로부터 만들어졌는지 역추적 조회\",\n        \"scenario\": \"특정 명령어 바이너리나 설정 파일이 시스템 어느 경로에 설치되었는지 원본 패키지 파일 매핑 확인\",\n        \"tags\": [\n            \"Rocky\",\n            \"dnf\",\n            \"rpm\",\n            \"패키지관리\",\n            \"EPEL\"\n        ]\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"mdadm RAID 어레이 정지 & 잔여 수퍼블록 초기화\",\n        \"cmd\": \"sudo mdadm -S /dev/md1 && sudo mdadm --zero-superblock /dev/nvme0n3 /dev/nvme0n4\",\n        \"desc\": \"기존 소프트웨어 RAID 어레이를 안전하게 정지(-S)하고, 디스크에 기록된 메타데이터(Superblock)를 0으로 덮어써 다른 용도나 LVM 물리 볼륨으로 재사용할 수 있도록 초기화합니다.\",\n        \"abbr\": \"mdadm -S(Stop Array: RAID 어레이 비활성화) · --zero-superblock(수퍼블록 데이터 완전 소거) — 사용이 끝난 소프트웨어 RAID 어레이를 안전하게 정지시키고, 디스크 헤더에 남아있는 RAID 메타데이터를 깨끗이 지워 일반 디스크나 LVM으로 재사용 가능하게 초기화\",\n        \"scenario\": \"테스트 완료된 RAID 디스크를 분해하여 신규 LVM 스토리지 풀이나 단일 파티션으로 전용\",\n        \"tags\": [\n            \"Rocky\",\n            \"mdadm\",\n            \"RAID해제\",\n            \"superblock\",\n            \"스토리지초기화\"\n        ]\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"grubby 부팅 기본 커널 확인 & 커널 파라미터 제어\",\n        \"cmd\": \"grubby --default-kernel && grubby --info=ALL | grep -E \\\"(index|kernel|title)\\\"\",\n        \"desc\": \"Rocky Linux 8/9/10에서 복잡한 grub.cfg 파일을 직접 건드리지 않고 공식 grubby CLI를 통해 부팅 시 기본 기동될 커널 버전과 등록된 전체 커널 목록을 안전하게 조회 및 제어합니다.\",\n        \"abbr\": \"grubby(GRUB 부트로더 설정 유틸리티) — Rocky Linux 8/9/10에서 복잡한 grub.cfg 파일을 직접 건드리지 않고, 부팅 시 기본으로 실행될 커널 버전과 시스템 부팅 옵션을 안전하게 조회 및 제어\",\n        \"scenario\": \"커널 업데이트 후 이전 안정 커널 롤백 지정 또는 부팅 매개변수(console, audit 등) 검증\",\n        \"tags\": [\n            \"Rocky\",\n            \"grubby\",\n            \"커널\",\n            \"부팅관리\",\n            \"GRUB\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker save/load 오프라인 컨테이너 이미지 이전\",\n        \"cmd\": \"docker save -o /tmp/web-image.tar test:nginx && scp /tmp/web-image.tar remote-host:/tmp/ && ssh remote-host \\\"docker load -i /tmp/web-image.tar\\\"\",\n        \"desc\": \"인터넷 접속이 제한된 폐쇄망이나 원격 레지스트리가 없는 환경에서 도커 이미지를 단일 tar 아카이브로 추출(save)하고 원격 서버에서 즉시 복원(load)합니다.\",\n        \"abbr\": \"docker save(도커 이미지를 tar 압축 파일로 추출) · docker load(tar 파일에서 도커 이미지 복원) — 인터넷이 완전히 차단된 폐쇄망 서버나 보안 구역으로 도커 이미지를 파일 형태로 안전하게 복사하여 이전\",\n        \"scenario\": \"외부 인터넷 연결이 차단된 엔터프라이즈 사설 인프라 및 보안 존으로 도커 컨테이너 이미지 무결성 전송\",\n        \"tags\": [\n            \"Docker\",\n            \"docker_save\",\n            \"docker_load\",\n            \"폐쇄망\",\n            \"이미지백업\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker cp 컨테이너와 호스트 간 실시간 파일 추출 & 주입\",\n        \"cmd\": \"docker cp web-server:/etc/nginx/nginx.conf ./nginx.conf && docker cp ./index.html web-server:/var/www/html/\",\n        \"desc\": \"컨테이너를 중지하지 않고 실행 중인 컨테이너 내부 파일(/etc/nginx/nginx.conf)을 호스트로 가져오거나, 호스트의 소스코드를 컨테이너 내부로 직접 밀어 넣습니다.\",\n        \"abbr\": \"docker cp(Docker Copy: 호스트와 컨테이너 파일시스템 간 양방향 복사) — 컨테이너를 중지시키지 않고도, 실행 중인 컨테이너 내부의 설정 파일이나 로그를 호스트로 꺼내오거나 호스트의 수정된 소스코드를 컨테이너 안으로 즉시 주입\",\n        \"scenario\": \"볼륨 마운트가 누락된 컨테이너에서 설정 파일 긴급 백업/분석 또는 긴급 패치 파일 즉시 반영\",\n        \"tags\": [\n            \"Docker\",\n            \"docker_cp\",\n            \"파일복사\",\n            \"핫픽스\",\n            \"디버깅\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"사설 Docker Registry REST API 이미지 & 태그 목록 질의\",\n        \"cmd\": \"curl -s http://localhost:5000/v2/_catalog | jq . && curl -s http://localhost:5000/v2/test/tags/list | jq .\",\n        \"desc\": \"자체 구축한 사설 Docker Registry v2 API 규격에 맞춰 저장소에 푸시된 전체 리포지토리 목록(_catalog)과 특정 이미지의 태그 리스트(tags/list)를 JSON으로 조회합니다.\",\n        \"abbr\": \"Registry v2 API(도커 원격 레지스트리 HTTP 표준 규격) — 별도의 웹 관리 화면이 없는 사설 Docker Registry 서버에서 현재 어떤 이미지 리포지토리들이 저장되어 있고 어떤 버전 태그들이 존재하는지 curl과 jq로 조회\",\n        \"scenario\": \"GUI 대시보드가 없는 자체 사설 레지스트리에서 현재 보관 중인 이미지 버전 및 태그 실시간 감사\",\n        \"tags\": [\n            \"Docker\",\n            \"Registry\",\n            \"REST_API\",\n            \"_catalog\",\n            \"사설저장소\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"원격 Docker 데몬 TCP 연결 (-H) 및 rdocker 관리\",\n        \"cmd\": \"docker -H tcp://192.168.120.128:2375 ps -a && echo \\\"alias rdocker='docker -H tcp://192.168.120.128:2375'\\\" >> ~/.bashrc\",\n        \"desc\": \"로컬 소켓(/var/run/docker.sock) 대신 네트워크 TCP 포트(2375)로 개방된 원격 호스트의 도커 엔진에 직접 접속하여 컨테이너 상태를 조회하고 명령을 내립니다.\",\n        \"abbr\": \"-H(Host: 접속할 원격 데몬 주소 지정) · rdocker(원격 도커 제어 단축 별칭) — 원격 리눅스 서버에 SSH로 일일이 로그인하지 않고, 내 로컬 컴퓨터 터미널에서 원격 서버의 도커 엔진에 직접 명령을 내려 원격 컨테이너를 제어\",\n        \"scenario\": \"Bastion 또는 관리자 로컬 PC에서 여러 원격 클라우드 서버의 도커 런타임을 원격 중앙 집중 제어\",\n        \"tags\": [\n            \"Docker\",\n            \"원격데몬\",\n            \"-H\",\n            \"rdocker\",\n            \"TCP바인딩\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker history 이미지 빌드 레이어 & 명령어 역추적\",\n        \"cmd\": \"docker history --no-trunc test:nginx | head -n 10\",\n        \"desc\": \"특정 이미지가 어떤 베이스 이미지와 어떤 Dockerfile 명령어(RUN, COPY, EXPOSE 등)를 거쳐 빌드되었는지 레이어별 용량과 생성 명령을 역추적합니다.\",\n        \"abbr\": \"history(이미지 레이어 생성 이력 조회) — Dockerfile 원본 소스가 없는 이미지일지라도, 이 이미지가 어떤 베이스 이미지 위에 어떤 명령어를 거쳐 만들어졌는지 레이어별 용량과 생성 과정을 역추적 분석\",\n        \"scenario\": \"타인이 빌드한 도커 이미지의 Dockerfile 원본이 유실되었을 때 빌드 과정 분석 및 이미지 용량 최적화 포인트 색출\",\n        \"tags\": [\n            \"Docker\",\n            \"history\",\n            \"레이어분석\",\n            \"용량최적화\",\n            \"이미지분석\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"모든 컨테이너 일괄 강제 삭제 및 정리 별칭 (drmall)\",\n        \"cmd\": \"echo \\\"alias drmall='docker rm -f \\\\$(docker ps -aq)'\\\" >> ~/.bashrc && docker rm -f $(docker ps -aq 2>/dev/null)\",\n        \"desc\": \"실행 중이거나 중지된 모든 컨테이너 ID(-aq)를 한 번에 조회하여 강제 삭제(-f)하는 실습용 필수 별칭 drmall을 구성하고 환경을 정리합니다.\",\n        \"abbr\": \"drmall(Docker Remove All: 모든 컨테이너 일괄 삭제 단축 별칭) — 실습이 끝난 후 실행 중인 컨테이너와 중지된 컨테이너를 가리지 않고 한 번에 강제 삭제(-f)하여 깨끗한 초기 상태로 시스템 리셋\",\n        \"scenario\": \"실습 종료 후 또는 새로운 프로젝트 배포 전 기존에 누적된 테스트 컨테이너들을 한 번에 클리어\",\n        \"tags\": [\n            \"Docker\",\n            \"drmall\",\n            \"일괄삭제\",\n            \"단축어\",\n            \"환경정리\"\n        ]\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker logs 컨테이너 실시간 로그 스트림 (-f, --tail)\",\n        \"cmd\": \"docker logs -f --tail=100 web-server\",\n        \"desc\": \"컨테이너 내부 표준 출력(stdout) 및 표준 에러(stderr) 로그를 최근 100줄부터 실시간(-f) 스트리밍하여 추적합니다.\",\n        \"scenario\": \"컨테이너가 비정상 동작하거나 500 에러 발생 시 애플리케이션 로그를 호스트 터미널에서 즉시 실시간 디버깅\",\n        \"tags\": [\n            \"Docker\",\n            \"logs\",\n            \"로그스트림\",\n            \"디버깅\",\n            \"모니터링\"\n        ],\n        \"abbr\": \"logs(로그 기록 조회) · -f(Follow: 끝까지 따라가며 실시간 출력) · --tail(꼬리: 최근 N개 라인부터 시작) — 컨테이너가 화면에 띄우는 애플리케이션 출력과 에러 메시지를 호스트 터미널에서 실시간으로 스트리밍 감시\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker stats 컨테이너별 CPU·메모리·네트워크 I/O 실시간 측정\",\n        \"cmd\": \"docker stats --no-stream\",\n        \"desc\": \"실행 중인 모든 컨테이너의 CPU 점유율, 메모리 사용량/제한치, 네트워크 I/O, 블록 I/O 지표를 단일 스냅샷 또는 실시간 스트림으로 조회합니다.\",\n        \"scenario\": \"특정 컨테이너의 메모리 누수(Memory Leak)나 CPU 100% 폭주 현상을 즉각 식별하고 리소스 한도 조율\",\n        \"tags\": [\n            \"Docker\",\n            \"stats\",\n            \"CPU\",\n            \"메모리\",\n            \"모니터링\",\n            \"성능\"\n        ],\n        \"abbr\": \"stats(Statistics: 자원 통계 지표) — 리눅스 top처럼 각 컨테이너가 호스트의 CPU와 메모리, 디스크, 네트워크를 얼마나 소모하고 있는지 실시간 계측\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker top 컨테이너 내부 프로세스(PID) 조회\",\n        \"cmd\": \"docker top web-server\",\n        \"desc\": \"컨테이너 내부에서 실행 중인 프로세스 목록과 호스트 기준 실제 PID, 부모 PID, 구동 사용자 정보를 조회합니다.\",\n        \"scenario\": \"컨테이너 안으로 exec 침투하지 않고도 어떤 데몬이 살아있는지 호스트 레벨에서 신속 점검\",\n        \"tags\": [\n            \"Docker\",\n            \"top\",\n            \"프로세스\",\n            \"PID\",\n            \"모니터링\"\n        ],\n        \"abbr\": \"top(Table of Processes: 프로세스 목록) — 컨테이너 격리 영역 안에서 돌고 있는 백그라운드 워커 프로세스와 호스트 OS 기준 실제 프로세스 ID(PID)를 외부에서 직접 확인\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker port 호스트와 컨테이너 간 포트 바인딩 확인\",\n        \"cmd\": \"docker port web-server\",\n        \"desc\": \"컨테이너의 내부 서비스 포트(예: 80/tcp)가 호스트의 어떤 IP와 포트로 노출(바인딩)되어 있는지 매핑 정보를 즉시 확인합니다.\",\n        \"scenario\": \"복수의 컨테이너가 배포된 서버에서 어떤 외부 포트가 특정 컨테이너와 연결되었는지 포트 충돌 여부 점검\",\n        \"tags\": [\n            \"Docker\",\n            \"port\",\n            \"포트포워딩\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"port(네트워크 접속 통로/포트 매핑) — 컨테이너가 호스트 머신의 몇 번 포트로 외부와 연결되어 통신하고 있는지 포트 바인딩 매핑 관계를 즉시 역추적\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker update 컨테이너 자동 재시작(restart=always) 정책 동적 부여\",\n        \"cmd\": \"docker update --restart=always web-server\",\n        \"desc\": \"컨테이너를 삭제하고 다시 띄우지 않고도 실행 중인 컨테이너에 시스템 재부팅 또는 비정상 종료 시 자동 재기동 정책을 부여합니다.\",\n        \"scenario\": \"호스트 서버 재부팅 후에도 필수 웹/DB 컨테이너가 수동 조작 없이 자동으로 복구되도록 고가용성(HA) 설정\",\n        \"tags\": [\n            \"Docker\",\n            \"update\",\n            \"restart\",\n            \"고가용성\",\n            \"자동복구\"\n        ],\n        \"abbr\": \"update(실행 중 설정 동적 갱신) · --restart=always(항상 재시작) — 컨테이너를 재생성할 필요 없이, 서버 재부팅이나 프로세스 강제 다운 시 컨테이너가 스스로 다시 살아나도록 자동 복구 정책을 주입\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"docker run -e 환경변수 주입 및 컨테이너 동적 제어\",\n        \"cmd\": \"docker run -d --name app-prod -e APP_ENV=production -e DB_HOST=10.0.0.5 -p 3000:3000 myapp:latest\",\n        \"desc\": \"이미지 내부 코드를 수정하지 않고 외부 환경변수(-e)를 통해 데이터베이스 접속 주소, 실행 모드(개발/운영), API 키 등을 동적으로 주입합니다.\",\n        \"scenario\": \"동일한 애플리케이션 이미지를 개발, 스테이징, 운영 환경에 코드 수정 없이 12-Factor 원칙에 맞춰 재사용 배포\",\n        \"tags\": [\n            \"Docker\",\n            \"환경변수\",\n            \"run\",\n            \"12Factor\",\n            \"설정관리\"\n        ],\n        \"abbr\": \"-e(Environment: 환경 변수 주입) — 컨테이너 이미지 자체를 수정하지 않고, 실행 시점에 외부에서 DB 주소나 실행 모드(DEV/PROD) 값을 주입하여 유연하게 환경을 전환하는 클라우드 네이티브 표준 방식\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker volume 네임드 볼륨 목록 & 호스트 실제 저장 경로(Mountpoint) 조회\",\n        \"cmd\": \"docker volume ls && docker volume inspect my-db-vol\",\n        \"desc\": \"도커가 관리하는 모든 네임드 볼륨 목록을 조회하고, inspect를 통해 호스트 파일시스템 상의 실제 물리 저장 경로(/var/lib/docker/volumes/...)를 확인합니다.\",\n        \"scenario\": \"컨테이너 데이터가 호스트 스토리지 어디에 안전하게 영속 저장되고 있는지 백업 대상 물리 디렉토리 경로 추적\",\n        \"tags\": [\n            \"Docker\",\n            \"volume\",\n            \"inspect\",\n            \"데이터영속성\",\n            \"백업\"\n        ],\n        \"abbr\": \"volume(독립 저장 공간) · inspect(세부 검사) — 도커가 관리하는 볼륨이 호스트 리눅스 디스크의 실제 어느 물리 경로(/var/lib/docker/volumes/...)에 저장되고 있는지 정확한 마운트포인트를 확인\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker network inspect 가상 네트워크 서브넷 & 연결 컨테이너 전수 점검\",\n        \"cmd\": \"docker network inspect bridge\",\n        \"desc\": \"지정한 도커 가상 네트워크의 서브넷 대역(Subnet), 기본 게이트웨이(Gateway), 그리고 연결된 컨테이너들의 사설 IP 목록과 MAC 주소를 확인합니다.\",\n        \"scenario\": \"컨테이너 간 통신 불능 장애 시 동일 네트워크 서브넷에 묶여 있는지 및 IP 충돌 여부 전수 진단\",\n        \"tags\": [\n            \"Docker\",\n            \"network\",\n            \"inspect\",\n            \"서브넷\",\n            \"가상스위치\"\n        ],\n        \"abbr\": \"network(가상 네트워크 스위치) · inspect(검사) — 도커가 생성한 가상 브릿지의 서브넷 대역폭(예: 172.17.0.0/16)과 게이트웨이, 그리고 여기에 연결된 컨테이너들의 사설 IP 목록을 일괄 검사\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L4\",\n        \"lvlName\": \"고급 L4\",\n        \"name\": \"docker compose down -v 컨테이너·네트워크·볼륨 일괄 완전 정리\",\n        \"cmd\": \"docker compose down -v --remove-orphans\",\n        \"desc\": \"compose로 띄운 컨테이너와 네트워크를 중지 및 삭제하고, -v 옵션으로 네임드 볼륨까지 함께 삭제하며, 이전 설정에 남은 고아 컨테이너를 정리합니다.\",\n        \"scenario\": \"테스트 완료 후 초기 상태로 완전히 초기화하거나 데이터베이스 스키마를 초기 상태부터 재실행해야 할 때\",\n        \"tags\": [\n            \"Compose\",\n            \"down\",\n            \"볼륨정리\",\n            \"초기화\",\n            \"오케스트레이션\"\n        ],\n        \"abbr\": \"down(스택 전체 정지 및 삭제) · -v(Volumes: 연계된 볼륨 데이터까지 완전 삭제) · --remove-orphans(정의에서 빠진 잔여 컨테이너 정리) — 개발/테스트 환경을 잔여 찌꺼기 없이 100% 최초 클린 상태로 초기화\"\n    },\n    {\n        \"cat\": \"docker\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"docker build --no-cache 캐시 무시 완전 재빌드\",\n        \"cmd\": \"docker build --no-cache -t my-app:latest .\",\n        \"desc\": \"이전 빌드 과정에서 호스트에 캐시된 중간 레이어를 재사용하지 않고, apt 최신 패키지나 원격 소스코드를 처음부터 완전히 새로 내려받아 빌드합니다.\",\n        \"scenario\": \"Dockerfile의 패키지 설치 명령(RUN apt update)이 캐시되어 최신 보안 패치가 누락되는 현상 방지\",\n        \"tags\": [\n            \"Docker\",\n            \"build\",\n            \"no-cache\",\n            \"클린빌드\",\n            \"Dockerfile\"\n        ],\n        \"abbr\": \"build(이미지 조립) · --no-cache(중간 저장된 캐시 레이어를 쓰지 않음) — 이전에 빌드했던 중간 결과를 건너뛰고 모든 레이어를 처음부터 다시 실행하여, 외부 최신 보안 업데이트나 최신 소스코드를 강제로 반영\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"dumpe2fs ext 파일시스템 슈퍼블록 & 블록 그룹 메타데이터 점검\",\n        \"cmd\": \"dumpe2fs -h /dev/nvme0n2p1\",\n        \"desc\": \"ext4 파일시스템의 슈퍼블록(Superblock) 정보를 읽어 블록 크기, 마운트 횟수, 파일시스템 상태, 예약 블록 수, UUID를 출력합니다.\",\n        \"scenario\": \"파일시스템 손상이 의심되거나 마운트 카운트 초과 점검 주기를 확인할 때 메타데이터 정밀 분석\",\n        \"tags\": [\n            \"ext4\",\n            \"dumpe2fs\",\n            \"슈퍼블록\",\n            \"메타데이터\",\n            \"디스크점검\"\n        ],\n        \"abbr\": \"dump(내용을 통째로 쏟아내다) + e2fs(ext2/3/4 File System) · -h(Header only: 슈퍼블록 요약만 표시) — 파일시스템 전체의 핵심 지도이자 관리 데이터인 '슈퍼블록(Superblock)'의 블록 크기와 상태 정보를 그대로 덤프하여 점검\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"tune2fs ext4 슈퍼블록 튜닝 (루트 예약 블록 5% ➔ 1% 축소)\",\n        \"cmd\": \"tune2fs -m 1 /dev/nvme0n2p1 && tune2fs -l /dev/nvme0n2p1 | grep \\\"Reserved block count\\\"\",\n        \"desc\": \"ext 파일시스템이 root 사용자를 위해 기본으로 5% 예약해두는 디스크 공간을 1%로 줄여 일반 데이터 가용 공간을 대폭 확보합니다.\",\n        \"scenario\": \"10TB 이상의 대용량 데이터 전용 스토리지에서 기본 5%(500GB)에 달하는 낭비 공간을 최소화하여 실제 용량 확보\",\n        \"tags\": [\n            \"ext4\",\n            \"tune2fs\",\n            \"예약블록\",\n            \"스토리지튜닝\",\n            \"디스크용량\"\n        ],\n        \"abbr\": \"tune(조율하다/최적화하다) + e2fs(ext2/3/4 File System) · -m(Reserved blocks percentage: 예약 비율) — 파일시스템을 재포맷하지 않고도 root 전용 예약 공간 비율이나 점검 주기를 운영 중에 즉시 미세 튜닝\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"xfs_info XFS 파일시스템 블록 구조 & AG 지오메트리 확인\",\n        \"cmd\": \"xfs_info /xfs\",\n        \"desc\": \"마운트된 XFS 파일시스템의 데이터 블록 크기, Allocation Group(agcount) 개수, 저널 로그 크기 등 지오메트리 구조를 조회합니다.\",\n        \"scenario\": \"XFS 무중단 확장(xfs_growfs) 전후의 블록 할당 그룹 변화 및 성능 튜닝 상태 검증\",\n        \"tags\": [\n            \"XFS\",\n            \"xfs_info\",\n            \"지오메트리\",\n            \"블록구조\",\n            \"스토리지\"\n        ],\n        \"abbr\": \"xfs(고성능 XFS 파일시스템) + info(Information: 정보) — RHEL/Rocky Linux의 표준 파일시스템인 XFS의 내부 블록 크기, 병렬 처리를 담당하는 Allocation Group(agcount) 구조를 정밀 확인\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"fdisk -l 디스크 물리 용량 및 파티션 테이블 빠른 조회\",\n        \"cmd\": \"fdisk -l /dev/nvme0n2\",\n        \"desc\": \"지정 디스크 또는 시스템 전체의 파티션 형식(MBR/GPT), 섹터 크기, 시작/끝 섹터, 파티션 식별자(Id/Type)를 신속하게 요약 출력합니다.\",\n        \"scenario\": \"새 디스크 장착 직후 장치명 식별 및 기존 파티션 잔여 정보 확인\",\n        \"tags\": [\n            \"fdisk\",\n            \"파티션\",\n            \"디스크조회\",\n            \"섹터\",\n            \"스토리지\"\n        ],\n        \"abbr\": \"fdisk(Fixed Disk: 고정 하드디스크 파티션 관리 도구) · -l(List: 목록 출력) — 디스크를 직접 수정하지 않고, 현재 디스크의 물리적 섹터 크기, 총 용량, 파티션 테이블 구조를 읽기 전용으로 안전하고 빠르게 조회\"\n    },\n    {\n        \"cat\": \"disk\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"lsblk -f 파일시스템(FSTYPE) · 마운트 지점 · UUID 한눈에 보기\",\n        \"cmd\": \"lsblk -f\",\n        \"desc\": \"블록 장치 트리와 함께 각 파티션의 포맷 형식(xfs, ext4, swap), 볼륨 레이블, UUID, 마운트 경로를 일목요연하게 표시합니다.\",\n        \"scenario\": \"/etc/fstab 영구 등록 시 복잡한 blkid 대신 파티션별 UUID와 파일시스템 타입을 한눈에 파악\",\n        \"tags\": [\n            \"lsblk\",\n            \"UUID\",\n            \"파일시스템\",\n            \"fstab\",\n            \"디스크\"\n        ],\n        \"abbr\": \"lsblk(List Block Devices: 블록 장치 목록) · -f(Filesystem: 파일시스템 정보 집중 표시) — 복잡한 파티션 계층과 함께 포맷된 파일시스템 형식(xfs/ext4)과 고유 UUID를 한눈에 정리하여 /etc/fstab 등록 오류 방지\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"timedatectl 타임존 설정(Asia/Seoul) & NTP 시간 동기화 점검\",\n        \"cmd\": \"timedatectl set-timezone Asia/Seoul && timedatectl status\",\n        \"desc\": \"서버의 표준 시간대를 KST(Asia/Seoul)로 즉시 변경하고, systemd-timesyncd 또는 NTP 데몬과의 시간 동기화 활성화 여부를 확인합니다.\",\n        \"scenario\": \"신규 서버 구축 시 UTC 기본값으로 인한 로그 기록 왜곡 방지 및 초정밀 서버 타임존 통일\",\n        \"tags\": [\n            \"timedatectl\",\n            \"타임존\",\n            \"NTP\",\n            \"시간동기화\",\n            \"systemd\"\n        ],\n        \"abbr\": \"timedate(시간과 날짜) + ctl(Control: 제어기) — 리눅스 시스템의 표준 시간대(Timezone)를 설정하고, 원격 시간 서버와의 네트워크 시간 동기화(NTP) 상태를 제어하는 systemd 통합 도구\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L3\",\n        \"lvlName\": \"중급 L3\",\n        \"name\": \"chronyc sources NTP 소스 서버 동기화 상태 및 오차(Offset) 추적\",\n        \"cmd\": \"chronyc sources -v && chronyc tracking\",\n        \"desc\": \"Chrony NTP 클라이언트를 통해 참조 중인 상위 타임 서버 소스 목록, 계층(Stratum), 도달율, 시간 오차(Offset/Skew)를 정밀 분석합니다.\",\n        \"scenario\": \"분산 데이터베이스나 쿠버네티스 노드 간 밀리초(ms) 단위 시계 불일치(Clock Drift) 장애 예방\",\n        \"tags\": [\n            \"chronyc\",\n            \"NTP\",\n            \"시간오차\",\n            \"Stratum\",\n            \"동기화\"\n        ],\n        \"abbr\": \"chrony(시간을 의미하는 Chronos) + c(Client: 클라이언트) · sources(동기화 대상 서버 출처) — 고정밀 타임 서버들과의 통신 상태를 확인하고, 서버 간 밀리초(ms) 단위 시계 오차(Clock Skew)를 정밀 보정\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"hostnamectl 서버 호스트명 영구 지정 & OS 요약 정보\",\n        \"cmd\": \"hostnamectl set-hostname rocky10-node01.ktcloud.internal && hostnamectl status\",\n        \"desc\": \"재부팅 후에도 유지되는 정적 호스트네임을 지정하고, 운영체제 버전, 커널 버전, 아키텍처, 하이퍼바이저 정보를 일괄 확인합니다.\",\n        \"scenario\": \"클라우드 인스턴스 프로비저닝 시 localhost 대신 표준화된 FQDN 서버 식별자 영구 등록\",\n        \"tags\": [\n            \"hostnamectl\",\n            \"호스트명\",\n            \"FQDN\",\n            \"systemd\",\n            \"서버정보\"\n        ],\n        \"abbr\": \"hostname(컴퓨터 이름) + ctl(Control: 제어기) — 네트워크에서 서버를 식별하는 컴퓨터 이름(Host Name)을 재부팅 후에도 유지되도록 영구 설정하고 운영체제/커널 요약을 확인\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"free -h -w 버퍼(buffers)와 캐시(cache) 분리 실가용 메모리 점검\",\n        \"cmd\": \"free -h -w\",\n        \"desc\": \"사람이 읽기 쉬운 단위(-h)와 함께 와이드 모드(-w)로 디스크 I/O 버퍼와 페이지 캐시를 분리하여 실제 가용(available) 메모리를 명확히 측정합니다.\",\n        \"scenario\": \"리눅스가 파일 캐시로 메모리를 소모하여 free 용량이 적어 보일 때 실제 애플리케이션 할당 가능 메모리 오독 방지\",\n        \"tags\": [\n            \"free\",\n            \"메모리\",\n            \"버퍼캐시\",\n            \"available\",\n            \"자원점검\"\n        ],\n        \"abbr\": \"free(여유 공간) · -h(Human readable: GB/MB 단위) · -w(Wide: 버퍼와 캐시를 분리 표기) — 리눅스는 여유 메모리를 디스크 캐시로 활용하므로, 'free' 숫자가 아니라 실제 사용 가능한 'available' 컬럼을 판독하는 핵심 도구\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"uptime 가동 시간 & CPU 부하 평균(Load Average 1/5/15분) 점검\",\n        \"cmd\": \"uptime\",\n        \"desc\": \"서버가 부팅된 후 연속 가동된 시간과 현재 접속 사용자 수, 그리고 최근 1분, 5분, 15분 동안 CPU 실행을 기다린 런큐 부하 평균을 출력합니다.\",\n        \"scenario\": \"서버 장애 발생 시 가장 먼저 1분 부하가 CPU 코어 수를 초과하여 치솟고 있는지 병목 신속 판정\",\n        \"tags\": [\n            \"uptime\",\n            \"LoadAverage\",\n            \"부하평균\",\n            \"가동시간\",\n            \"성능점검\"\n        ],\n        \"abbr\": \"uptime(Up Time: 서버가 살아있는 가동 시간) — 서버가 켜진 이후 경과 시간과 함께 1분, 5분, 15분 단위의 '부하 평균(Load Average)'을 통해 CPU 런큐 병목 여부를 1초 만에 판별\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"dmesg -T 커널 링 버퍼 하드웨어 에러 & OOM 킬러 메시지 조회\",\n        \"cmd\": \"dmesg -T --level=err,warn | tail -n 25\",\n        \"desc\": \"커널 부팅 및 런타임 이벤트 링 버퍼에서 타임스탬프(-T)와 함께 심각도(err, warn)를 필터링하여 디스크 에러, OOM 킬러, 네트워크 링크 드롭을 역추적합니다.\",\n        \"scenario\": \"프로세스가 이유 없이 사망했거나 하드웨어/디스크 I/O 오류로 시스템이 멈칫거릴 때 커널의 직접 경고 확인\",\n        \"tags\": [\n            \"dmesg\",\n            \"커널로그\",\n            \"OOM\",\n            \"하드웨어에러\",\n            \"장애분석\"\n        ],\n        \"abbr\": \"dmesg(Display Message: 커널 메시지 버퍼 출력) · -T(Human readable timestamp: 실제 날짜와 시각 표기) — 리눅스 커널이 메모리 링 버퍼에 기록해둔 하드웨어 이상, OOM 메모리 강제 종료, 드라이버 오류를 실시간 추적\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"crontab 분·시·일·월·요일 주기적 배치 스케줄 등록 및 조회\",\n        \"cmd\": \"crontab -l && crontab -e\",\n        \"desc\": \"정해진 주기(예: 0 3 * * * /backup/daily.sh)마다 셸 스크립트나 배치 작업을 자동으로 실행하도록 cron 데몬에 일정을 등록하고 관리합니다.\",\n        \"scenario\": \"새벽 3시 정기 데이터베이스 덤프 백업, 매시간 임시 파일 정리, 5분 주기 헬스체크 자동화\",\n        \"tags\": [\n            \"crontab\",\n            \"배치\",\n            \"스케줄링\",\n            \"자동화\",\n            \"cron\"\n        ],\n        \"abbr\": \"crontab(Chronos Table: 시간의 신 크로노스의 시간표) — '분 시 일 월 요일' 5가지 시간 규칙을 정의하여 정기 백업이나 주기적 스크립트를 백그라운드에서 자동 실행시키는 예약 작업 관리자\"\n    },\n    {\n        \"cat\": \"process\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"history 타임스탬프 포함 명령어 실행 이력 추적\",\n        \"cmd\": \"HISTTIMEFORMAT=\\\"%F %T \\\" history | tail -n 20\",\n        \"desc\": \"현재 셸 및 이전 세션에서 실행된 명령어 번호와 정확한 실행 시각(연-월-일 시:분:초)을 역추적하여 작업 감사 로그를 확인합니다.\",\n        \"scenario\": \"장애 발생 직전 어떤 엔지니어가 어떤 명령어를 입력했는지 작업 시점 역추적 및 이전 복잡 명령 재사용(!번호)\",\n        \"tags\": [\n            \"history\",\n            \"작업이력\",\n            \"감사로그\",\n            \"bash\",\n            \"트러블슈팅\"\n        ],\n        \"abbr\": \"history(실행 역사/이력) · HISTTIMEFORMAT(명령어 실행 시각 포맷) — 과거에 터미널에서 실행했던 모든 명령어들을 시간 순서대로 기록하여 누가 언제 어떤 작업을 수행했는지 감사 및 복기\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"tar -czvf 아카이브 압축 & -tzvf 압축 해제 전 내용물 사전 검증\",\n        \"cmd\": \"tar -czvf /backup/app-$(date +%F).tar.gz /var/www/html && tar -tzvf /backup/app-*.tar.gz | head -n 10\",\n        \"desc\": \"디렉토리 전체를 gzip(-z)으로 압축 아카이빙하고, 풀지 않고도(-t) 내부 파일 목록과 권한을 사전에 안전하게 검증합니다.\",\n        \"scenario\": \"배포 소스코드 패키징 및 대용량 디렉토리 단일 파일 백업 생성\",\n        \"tags\": [\n            \"tar\",\n            \"압축\",\n            \"아카이브\",\n            \"백업\",\n            \"gzip\"\n        ],\n        \"abbr\": \"tar(Tape Archive: 테이프 아카이브) · -c(Create 생성) · -x(eXtract 해제) · -t(Table of contents 목록 조회) · -z(gzip 압축) · -v(Verbose 진행 표시) · -f(File 대상 파일 지정) — 여러 파일과 폴더 구조를 권한 그대로 단일 아카이브로 패키징\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"which · whereis · type 명령어 실행 파일 위치 및 빌트인 식별\",\n        \"cmd\": \"which nginx && whereis python3 && type -a cd\",\n        \"desc\": \"명령어가 실제 어떤 경로의 실행 파일(바이너리)인지(PATH 탐색), 매뉴얼 위치는 어디인지, 또는 셸 내장 함수(builtin/alias)인지 판별합니다.\",\n        \"scenario\": \"여러 버전의 파이썬/도커가 설치되어 의도치 않은 이전 버전이 실행되는 PATH 우선순위 충돌 디버깅\",\n        \"tags\": [\n            \"which\",\n            \"whereis\",\n            \"type\",\n            \"바이너리\",\n            \"PATH\",\n            \"셸\"\n        ],\n        \"abbr\": \"which(어느 실행 파일인가) · whereis(바이너리와 매뉴얼 위치) · type(셸 내장어/별칭/외부 파일 구분) — 내가 타이핑한 명령어가 시스템의 어느 디렉토리에 존재하는 파일인지 우선순위를 판별\"\n    },\n    {\n        \"cat\": \"file\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"scp 보안 SSH 터널 기반 원격 서버 파일/디렉토리 전송\",\n        \"cmd\": \"scp -P 2222 -r /local/data user@192.168.10.50:/remote/backup/\",\n        \"desc\": \"SSH 암호화 세션을 통해 원격 서버와 로컬 호스트 간에 파일이나 디렉토리(-r)를 안전하게 원격 복사합니다.\",\n        \"scenario\": \"클라우드 가상머신으로 배포 패키지 전송 및 원격 서버의 덤프 파일을 로컬로 안전하게 다운로드\",\n        \"tags\": [\n            \"scp\",\n            \"SSH\",\n            \"원격전송\",\n            \"파일복사\",\n            \"보안\"\n        ],\n        \"abbr\": \"scp(Secure Copy: 보안 암호화 복사) · -P(Port 포트 지정) · -r(Recursive 디렉토리 재귀 복사) — SSH 프로토콜의 강력한 암호화 터널을 이용하여 로컬과 원격 서버 간에 안전하게 파일을 주고받음\"\n    },\n    {\n        \"cat\": \"text\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"alias 자주 쓰는 복잡한 명령어 단축어 등록 & 해제\",\n        \"cmd\": \"alias dps='docker ps --format \\\"table {{.Names}}\\\\t{{.Status}}\\\\t{{.Ports}}\\\"' && alias k='kubectl' && unalias dps\",\n        \"desc\": \"자주 사용하는 긴 옵션 조합 명령어를 짧은 별칭으로 등록하여 작업 생산성을 극대화하고 필요 시 해제합니다.\",\n        \"scenario\": \"매일 수십 번씩 입력하는 긴 도커 포맷 조회나 리눅스 파이프라인 명령어를 2~3글자 단축키로 표준화\",\n        \"tags\": [\n            \"alias\",\n            \"unalias\",\n            \"단축어\",\n            \"bash\",\n            \"생산성\"\n        ],\n        \"abbr\": \"alias(별칭/가명) · unalias(별칭 해제) — 매번 입력하기 번거로운 긴 옵션이나 복합 파이프라인 명령어에 나만의 짧은 이름을 붙여 즉시 실행\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"ip route 라우팅 테이블 & 목적지 패킷 출구(인터페이스) 추적\",\n        \"cmd\": \"ip route show && ip route get 8.8.8.8\",\n        \"desc\": \"리눅스 커널의 네트워크 라우팅 테이블과 기본 게이트웨이(default via)를 확인하고, 특정 목적지 IP로 갈 때 패킷이 타는 경로를 시뮬레이션합니다.\",\n        \"scenario\": \"외부 인터넷(8.8.8.8)과 통신되지 않을 때 기본 게이트웨이 설정 누락 여부 및 인터페이스 바인딩 점검\",\n        \"tags\": [\n            \"ip\",\n            \"route\",\n            \"게이트웨이\",\n            \"라우팅테이블\",\n            \"네트워크\"\n        ],\n        \"abbr\": \"ip route(IP 패킷 이동 경로 규칙) · default via(기본 통로/게이트웨이 IP) — 내 컴퓨터의 데이터 패킷이 외부 인터넷이나 다른 대역 네트워크로 나갈 때 어느 문(Gateway)과 랜카드로 나가야 하는지 결정하는 이정표\"\n    },\n    {\n        \"cat\": \"net\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"nmcli dev status 네트워크 카드 물리적 연결 & 관리 상태 점검\",\n        \"cmd\": \"nmcli dev status && nmcli con show --active\",\n        \"desc\": \"NetworkManager가 제어하는 물리 이더넷 카드, 가상 브릿지, 루프백 디바이스의 연결 상태(connected/unmanaged)를 확인합니다.\",\n        \"scenario\": \"네트워크 케이블 단선, 가상 랜카드 인식 불량 또는 NetworkManager 비관리 상태로 인한 통신 단절 신속 진단\",\n        \"tags\": [\n            \"nmcli\",\n            \"네트워크\",\n            \"NetworkManager\",\n            \"인터페이스\",\n            \"장치점검\"\n        ],\n        \"abbr\": \"nmcli(NetworkManager Command Line Interface) · dev status(Device Status: 네트워크 장치 하드웨어 상태) — 유선 랜카드나 가상 어댑터가 운영체제에 제대로 연결되어 작동 중인지 하드웨어 상태 점검\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"ssh-keygen & ssh-copy-id 무암호(Passwordless) Ed25519 공개키 인증 등록\",\n        \"cmd\": \"ssh-keygen -t ed25519 -C \\\"admin@ktci5\\\" -N \\\"\\\" -f ~/.ssh/id_ed25519 && ssh-copy-id -i ~/.ssh/id_ed25519.pub user@192.168.10.50\",\n        \"desc\": \"차세대 고보안 Ed25519 암호화 키 쌍을 생성하고, 원격 서버의 authorized_keys에 공개키를 자동으로 전송하여 패스워드 입력 없이 안전하게 자동 로그인하도록 설정합니다.\",\n        \"scenario\": \"Ansible, CI/CD 배포 스크립트, 관리자 자동화 파이프라인에서 보안 비밀번호 하드코딩 없이 안전한 키 기반 원격 접속\",\n        \"tags\": [\n            \"SSH\",\n            \"ssh-keygen\",\n            \"ssh-copy-id\",\n            \"Ed25519\",\n            \"공개키인증\"\n        ],\n        \"abbr\": \"ssh-keygen(SSH Key Generator: 키 생성기) · ssh-copy-id(공개키 자동 복사) — 비밀번호를 매번 치는 대신 수학적으로 뚫기 불가능한 공개키-개인키 쌍을 만들어 원격 서버에 등록함으로써 무암호 고보안 자동 로그인 구현\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L1\",\n        \"lvlName\": \"기초 L1\",\n        \"name\": \"useradd & usermod 사용자 계정 생성 및 sudo/wheel 관리자 그룹 배속\",\n        \"cmd\": \"sudo useradd -m -s /bin/bash deployer && sudo usermod -aG wheel deployer && id deployer\",\n        \"desc\": \"홈 디렉토리(-m)와 기본 셸(-s)을 갖춘 신규 계정을 생성하고, Rocky Linux 표준 관리자 그룹(wheel)에 추가하여 sudo 권한을 부여합니다.\",\n        \"scenario\": \"root 계정 직접 로그인을 차단하고 개발자/운영자별 개별 책임 계정 발급 및 권한 통제\",\n        \"tags\": [\n            \"useradd\",\n            \"usermod\",\n            \"사용자계정\",\n            \"wheel\",\n            \"sudo\",\n            \"보안\"\n        ],\n        \"abbr\": \"useradd(사용자 추가) · usermod(User Modify: 사용자 정보 수정) · -aG(Append to Group: 기존 그룹을 유지한 채 새 보조 그룹 추가) — 개별 엔지니어 전용 계정을 만들고 관리자 권한 그룹에 안전하게 편입\"\n    },\n    {\n        \"cat\": \"sec\",\n        \"lvl\": \"L2\",\n        \"lvlName\": \"기본 L2\",\n        \"name\": \"groupadd & gpasswd 프로젝트 팀 그룹 생성 및 멤버 등록\",\n        \"cmd\": \"sudo groupadd devops && sudo gpasswd -a deployer devops && getent group devops\",\n        \"desc\": \"신규 프로젝트 그룹을 생성하고, 팀원 계정을 그룹에 편입하여 공유 디렉토리 협업 권한(SGID)을 일괄 제어합니다.\",\n        \"scenario\": \"공동 개발 서버에서 여러 엔지니어가 동일한 디렉토리에 파일 쓰기/수정 권한을 공유할 수 있도록 그룹 단위 권한 설계\",\n        \"tags\": [\n            \"groupadd\",\n            \"gpasswd\",\n            \"그룹관리\",\n            \"권한공유\",\n            \"협업\"\n        ],\n        \"abbr\": \"groupadd(새 그룹 생성) · gpasswd(Group Password & Member: 그룹 멤버 추가 및 관리) — 파일이나 디렉토리 권한을 사용자 한 명씩 주지 않고, 팀 단위 그룹으로 묶어서 일괄 통제\"\n    }\n];\n\n    let currentCat = 'all';\n    let currentLvl = 'all';\n    let currentQuery = '';\n    let currentTag = 'all';\n    let currentView = 'card'; // 'card' or 'table'\n\n    const grid = document.getElementById('cardsGrid');\n    const tableView = document.getElementById('tableView');\n    const tableBody = document.getElementById('tableBody');\n    const searchInput = document.getElementById('searchInput');\n    const clearSearchBtn = document.getElementById('clearSearchBtn');\n    const itemCount = document.getElementById('itemCount');\n    const subtagChips = document.getElementById('subtagChips');\n    const viewCardBtn = document.getElementById('viewCardBtn');\n    const viewTableBtn = document.getElementById('viewTableBtn');\n    const resetAllBtn = document.getElementById('resetAllBtn');\n    const toast = document.getElementById('toast');\n    const toastMsg = document.getElementById('toastMsg');\n\n    // Popular tags per category\n    const categoryTagsMap = {\n      all: ['Docker', 'LVM', 'parted', 'Compose', 'systemd', 'SELinux', 'RAID', 'Swap', 'awk', 'SSH', '모니터링'],\n      docker: ['run', 'ps', 'exec', 'Dockerfile', 'Compose', '네트워크', '볼륨', 'logs', 'stats', '레지스트리', '모니터링'],\n      disk: ['LVM', 'parted', 'RAID', 'Swap', 'XFS', 'ext4', 'fstab', 'NFS', 'dumpe2fs', 'tune2fs'],\n      process: ['systemd', 'timedatectl', 'chronyc', 'hostnamectl', 'free', 'uptime', 'dmesg', 'crontab', 'history'],\n      sec: ['sudo', 'SELinux', 'firewall-cmd', 'SSH', 'ssh-keygen', 'useradd', 'groupadd', 'chattr'],\n      file: ['tar', 'find', 'which', 'scp', 'rsync', 'mkdir', 'ln'],\n      net: ['ip', 'route', 'ss', 'curl', 'nmcli', 'tcpdump', 'nc'],\n      text: ['awk', 'sed', 'grep', 'tail', 'jq', 'alias'],\n      sre: ['bpftrace', 'vmstat', 'sysctl', '커널튜닝'],\n      scenario: ['진단', '파이프라인', 'OOM', '디스크100%', '컨테이너종료']\n    };\n\n    function getLvlBadgeClass(lvl) {\n      switch(lvl) {\n        case 'L1': return 'bg-emerald-950 text-emerald-300 border border-emerald-800/60';\n        case 'L2': return 'bg-blue-950 text-blue-300 border border-blue-800/60';\n        case 'L3': return 'bg-purple-950 text-purple-300 border border-purple-800/60';\n        case 'L4': return 'bg-amber-950 text-amber-300 border border-amber-800/60';\n        case 'L5': return 'bg-rose-950 text-rose-300 border border-rose-800/60';\n        default: return 'bg-indigo-950 text-indigo-300 border border-indigo-800/60';\n      }\n    }\n\n    function getCatBadge(cat) {\n      switch(cat) {\n        case 'docker': return '<span class=\"text-cyan-400 font-bold\">🐳 도커</span>';\n        case 'disk': return '<span class=\"text-emerald-400 font-bold\">💾 디스크</span>';\n        case 'process': return '<span class=\"text-blue-400 font-bold\">⚙️ 시스템</span>';\n        case 'sec': return '<span class=\"text-amber-400 font-bold\">🔒 보안</span>';\n        case 'file': return '<span class=\"text-slate-300 font-bold\">📁 파일</span>';\n        case 'net': return '<span class=\"text-purple-400 font-bold\">🌐 망/소켓</span>';\n        case 'text': return '<span class=\"text-teal-400 font-bold\">📜 텍스트</span>';\n        case 'sre': return '<span class=\"text-rose-400 font-bold\">🔥 SRE</span>';\n        case 'scenario': return '<span class=\"text-indigo-400 font-bold\">💼 시나리오</span>';\n        default: return '<span class=\"text-slate-400 font-bold\">CLI</span>';\n      }\n    }\n\n    function renderSubtags() {\n      const tags = categoryTagsMap[currentCat] || categoryTagsMap.all;\n      subtagChips.innerHTML = [\n        `<button class=\"tag-chip px-2 py-0.5 rounded-full border text-[11px] transition-all ${currentTag === 'all' ? 'active-tag' : 'bg-slate-900 border-slate-700 text-slate-400 hover:text-white hover:border-slate-500'}\" data-tag=\"all\">#전체</button>`,\n        ...tags.map(t => `<button class=\"tag-chip px-2 py-0.5 rounded-full border text-[11px] transition-all ${currentTag === t ? 'active-tag' : 'bg-slate-900 border-slate-700 text-slate-400 hover:text-white hover:border-slate-500'}\" data-tag=\"${t}\">#${t}</button>`)\n      ].join('');\n\n      subtagChips.querySelectorAll('.tag-chip').forEach(btn => {\n        btn.addEventListener('click', () => {\n          currentTag = btn.dataset.tag;\n          renderSubtags();\n          render();\n        });\n      });\n    }\n\n    function render() {\n      const q = currentQuery.trim().toLowerCase();\n      \n      const filtered = data.filter(item => {\n        const matchCat = currentCat === 'all' || item.cat === currentCat;\n        const matchLvl = currentLvl === 'all' || item.lvl === currentLvl;\n        const matchTag = currentTag === 'all' || item.tags.some(t => t.toLowerCase() === currentTag.toLowerCase());\n        \n        const matchQ = !q || \n                       item.name.toLowerCase().includes(q) || \n                       (item.abbr && item.abbr.toLowerCase().includes(q)) || \n                       item.cmd.toLowerCase().includes(q) || \n                       item.desc.toLowerCase().includes(q) || \n                       item.scenario.toLowerCase().includes(q) || \n                       item.tags.some(t => t.toLowerCase().includes(q));\n        return matchCat && matchLvl && matchTag && matchQ;\n      });\n\n      // Update counter\n      if (q || currentCat !== 'all' || currentLvl !== 'all' || currentTag !== 'all') {\n        itemCount.innerHTML = `총 ${data.length}개 중 <span class=\"text-blue-400 font-bold\">${filtered.length}개</span> 표시 중`;\n        resetAllBtn.classList.remove('hidden');\n      } else {\n        itemCount.textContent = `총 ${data.length}개 항목 표시 중`;\n        resetAllBtn.classList.add('hidden');\n      }\n\n      clearSearchBtn.classList.toggle('hidden', !q);\n\n      if (filtered.length === 0) {\n        const emptyHtml = `\n          <div class=\"col-span-full py-16 text-center text-slate-500\">\n            <div class=\"text-4xl mb-3\">🔍</div>\n            <p class=\"text-base font-semibold text-slate-300\">일치하는 실무 명령어가 없습니다.</p>\n            <p class=\"text-xs mt-1 text-slate-500\">다른 검색어를 입력하시거나 카테고리/태그 필터를 초기화해 보세요.</p>\n            <button onclick=\"resetFilters()\" class=\"mt-4 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-xs font-semibold\">필터 전체 초기화</button>\n          </div>\n        `;\n        if (currentView === 'card') {\n          grid.innerHTML = emptyHtml;\n          grid.classList.remove('hidden');\n          tableView.classList.add('hidden');\n        } else {\n          tableBody.innerHTML = `<tr><td colspan=\"5\" class=\"py-12\">${emptyHtml}</td></tr>`;\n          tableView.classList.remove('hidden');\n          grid.classList.add('hidden');\n        }\n        return;\n      }\n\n      if (currentView === 'card') {\n        grid.classList.remove('hidden');\n        tableView.classList.add('hidden');\n\n        grid.innerHTML = filtered.map(item => `\n          <div class=\"rounded-xl bg-slate-950 border border-slate-800 p-5 flex flex-col justify-between hover:border-slate-700 transition-all hover:shadow-xl group\">\n            <div>\n              <div class=\"flex items-center justify-between gap-2 mb-3\">\n                <div class=\"flex items-center gap-1.5\">\n                  <span class=\"text-xs font-semibold px-2 py-0.5 rounded ${getLvlBadgeClass(item.lvl)}\">${item.lvlName}</span>\n                  ${getCatBadge(item.cat)}\n                </div>\n                <div class=\"flex flex-wrap gap-1 justify-end\">\n                  ${item.tags.slice(0, 3).map(t => `<span class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-900 text-slate-400 border border-slate-800\">#${t}</span>`).join('')}\n                </div>\n              </div>\n              \n              <h4 class=\"text-base font-bold text-white group-hover:text-blue-400 transition-colors\">${item.name}</h4>\n              \n              ${item.abbr ? `\n                <div class=\"mt-2.5 mb-2 px-3 py-2 rounded-lg bg-slate-900/95 border border-amber-500/20 flex items-start gap-2 text-[11px] leading-relaxed\">\n                  <span class=\"text-amber-400 font-bold shrink-0\">💡 용어 설명:</span>\n                  <span class=\"text-slate-300 font-medium font-mono\">${item.abbr}</span>\n                </div>\n              ` : ''}\n\n              <p class=\"text-xs text-slate-400 mt-1.5 leading-relaxed\">${item.desc}</p>\n              \n              <div class=\"mt-4 mb-2\">\n                <div class=\"flex items-center justify-between text-[11px] text-slate-500 mb-1\">\n                  <span class=\"font-medium\">실행 구문</span>\n                  <button onclick=\"copyCmd(this, '${item.cmd.replace(/\\\\/g, \"\\\\\\\\\").replace(/'/g, \"\\\\'\").replace(/\\n/g, \"\\\\n\")}')\" \n                          class=\"copy-btn hover:text-blue-400 text-slate-400 transition-colors font-sans flex items-center gap-1 font-semibold\">\n                    <span>📋</span> <span class=\"btn-lbl\">복사</span>\n                  </button>\n                </div>\n                <div class=\"bg-slate-900 rounded-lg p-3 font-mono text-xs text-blue-300 border border-slate-800/80 overflow-x-auto select-all whitespace-pre\">\n                  ${escapeHtml(item.cmd)}\n                </div>\n              </div>\n            </div>\n\n            <div class=\"mt-4 pt-3 border-t border-slate-900 flex items-start gap-2 text-xs text-slate-400\">\n              <span class=\"text-emerald-400 font-semibold shrink-0\">💡 실무:</span>\n              <span class=\"leading-tight text-slate-300\">${item.scenario}</span>\n            </div>\n          </div>\n        `).join('');\n\n      } else {\n        // Table View\n        grid.classList.add('hidden');\n        tableView.classList.remove('hidden');\n\n        tableBody.innerHTML = filtered.map(item => `\n          <tr class=\"hover:bg-slate-900/60 transition-colors group\">\n            <td class=\"py-3 px-3.5 align-top whitespace-nowrap\">\n              <div class=\"flex flex-col gap-1\">\n                <div>${getCatBadge(item.cat)}</div>\n                <span class=\"text-[10px] font-semibold px-1.5 py-0.5 rounded w-fit ${getLvlBadgeClass(item.lvl)}\">${item.lvlName}</span>\n              </div>\n            </td>\n            <td class=\"py-3 px-3.5 align-top\">\n              <div class=\"font-bold text-white group-hover:text-blue-400 transition-colors text-xs\">${item.name}</div>\n              <div class=\"mt-1 bg-slate-900 rounded px-2.5 py-1.5 font-mono text-[11px] text-blue-300 border border-slate-800/80 overflow-x-auto whitespace-pre select-all\">${escapeHtml(item.cmd)}</div>\n            </td>\n            <td class=\"py-3 px-3.5 align-top\">\n              <div class=\"text-xs text-slate-300 leading-snug\">${item.desc}</div>\n              <div class=\"mt-1.5 text-[11px] text-emerald-400 leading-tight flex items-start gap-1\">\n                <span class=\"shrink-0 font-bold\">↳ 실무:</span>\n                <span class=\"text-slate-400\">${item.scenario}</span>\n              </div>\n            </td>\n            <td class=\"py-3 px-3.5 align-top font-mono text-[11px] text-slate-300 leading-relaxed bg-slate-900/20\">\n              <span class=\"text-amber-400 font-bold\">💡</span> ${item.abbr || '-'}\n            </td>\n            <td class=\"py-3 px-3.5 align-middle text-center\">\n              <button onclick=\"copyCmd(this, '${item.cmd.replace(/\\\\/g, \"\\\\\\\\\").replace(/'/g, \"\\\\'\").replace(/\\n/g, \"\\\\n\")}')\" \n                      class=\"copy-btn px-2 py-1.5 rounded bg-slate-800 hover:bg-blue-600 text-slate-300 hover:text-white transition-all text-xs font-semibold flex items-center justify-center gap-1 mx-auto\" \n                      title=\"명령어 복사\">\n                <span>📋</span>\n              </button>\n            </td>\n          </tr>\n        `).join('');\n      }\n    }\n\n    function escapeHtml(str) {\n      return str.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\").replace(/'/g, \"&#039;\");\n    }\n\n    window.copyCmd = function(btnElement, text) {\n      navigator.clipboard.writeText(text).then(() => {\n        showToast('명령어가 클립보드에 복사되었습니다!');\n        if (btnElement) {\n          const lbl = btnElement.querySelector('.btn-lbl');\n          if (lbl) {\n            const old = lbl.textContent;\n            lbl.textContent = '복사됨!';\n            btnElement.classList.add('text-emerald-400');\n            setTimeout(() => {\n              lbl.textContent = old;\n              btnElement.classList.remove('text-emerald-400');\n            }, 1500);\n          } else {\n            const old = btnElement.innerHTML;\n            btnElement.innerHTML = '<span>✓</span>';\n            btnElement.classList.add('bg-emerald-600', 'text-white');\n            setTimeout(() => {\n              btnElement.innerHTML = old;\n              btnElement.classList.remove('bg-emerald-600', 'text-white');\n            }, 1500);\n          }\n        }\n      });\n    };\n\n    function showToast(msg) {\n      toastMsg.textContent = msg;\n      toast.classList.remove('translate-y-20', 'opacity-0');\n      toast.classList.add('translate-y-0', 'opacity-100');\n      setTimeout(() => {\n        toast.classList.add('translate-y-20', 'opacity-0');\n        toast.classList.remove('translate-y-0', 'opacity-100');\n      }, 2000);\n    }\n\n    window.resetFilters = function() {\n      currentCat = 'all';\n      currentLvl = 'all';\n      currentTag = 'all';\n      currentQuery = '';\n      searchInput.value = '';\n      \n      document.querySelectorAll('.cat-btn').forEach(b => {\n        const c = b.dataset.cat;\n        if (c === 'all') {\n          b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-blue-600 text-white flex items-center gap-1.5 shadow-md shadow-blue-600/20';\n        } else if (c === 'docker') {\n          b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-cyan-950/80 text-cyan-300 border border-cyan-700/60 hover:bg-cyan-900/80 flex items-center gap-1.5';\n        } else if (c === 'disk') {\n          b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-emerald-950/80 text-emerald-300 border border-emerald-700/60 hover:bg-emerald-900/80 flex items-center gap-1.5';\n        } else if (c === 'scenario') {\n          b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-indigo-900/60 text-indigo-300 border border-indigo-500/30 hover:bg-indigo-800/60 flex items-center gap-1.5';\n        } else {\n          b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5';\n        }\n      });\n\n      document.querySelectorAll('.lvl-btn').forEach(b => b.classList.remove('active-lvl'));\n      document.querySelector('.lvl-btn[data-lvl=\"all\"]').classList.add('active-lvl');\n\n      renderSubtags();\n      render();\n    };\n\n    resetAllBtn.addEventListener('click', window.resetFilters);\n\n    // View Switcher Handlers\n    viewCardBtn.addEventListener('click', () => {\n      currentView = 'card';\n      viewCardBtn.classList.add('active-view');\n      viewTableBtn.classList.remove('active-view');\n      render();\n    });\n\n    viewTableBtn.addEventListener('click', () => {\n      currentView = 'table';\n      viewTableBtn.classList.add('active-view');\n      viewCardBtn.classList.remove('active-view');\n      render();\n    });\n\n    // Category Tabs Handler\n    document.querySelectorAll('.cat-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        document.querySelectorAll('.cat-btn').forEach(b => {\n          const c = b.dataset.cat;\n          if (c === 'docker') {\n            b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-cyan-950/80 text-cyan-300 border border-cyan-700/60 hover:bg-cyan-900/80 flex items-center gap-1.5';\n          } else if (c === 'disk') {\n            b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-emerald-950/80 text-emerald-300 border border-emerald-700/60 hover:bg-emerald-900/80 flex items-center gap-1.5';\n          } else if (c === 'scenario') {\n            b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-indigo-900/60 text-indigo-300 border border-indigo-500/30 hover:bg-indigo-800/60 flex items-center gap-1.5';\n          } else {\n            b.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-slate-800 text-slate-300 hover:bg-slate-700 flex items-center gap-1.5';\n          }\n        });\n        btn.className = 'cat-btn shrink-0 px-3 py-2 rounded-lg font-medium transition-all bg-blue-600 text-white flex items-center gap-1.5 shadow-md shadow-blue-600/20';\n        currentCat = btn.dataset.cat;\n        currentTag = 'all'; // reset tag when switching category\n        renderSubtags();\n        render();\n      });\n    });\n\n    // Level Filter Handlers\n    document.querySelectorAll('.lvl-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        document.querySelectorAll('.lvl-btn').forEach(b => b.classList.remove('active-lvl'));\n        btn.classList.add('active-lvl');\n        currentLvl = btn.dataset.lvl;\n        render();\n      });\n    });\n\n    // Search Input\n    searchInput.addEventListener('input', (e) => {\n      currentQuery = e.target.value;\n      render();\n    });\n\n    clearSearchBtn.addEventListener('click', () => {\n      searchInput.value = '';\n      currentQuery = '';\n      render();\n      searchInput.focus();\n    });\n\n    window.addEventListener('keydown', (e) => {\n      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {\n        e.preventDefault();\n        searchInput.focus();\n      }\n      if (e.key === 'Escape' && document.activeElement === searchInput) {\n        searchInput.value = '';\n        currentQuery = '';\n        render();\n        searchInput.blur();\n      }\n    });\n\n    // Initial render\n    renderSubtags();\n    render();\n  </script>\n</body>\n</html>\n";
